//! Reading request bodies the way the original's Jackson `ObjectMapper`
//! (`ShogunCoreJsonObjectMapper`, default features) does:
//!
//! * an unknown property is an error (`FAIL_ON_UNKNOWN_PROPERTIES`);
//! * properties with an ignored getter (`created`, `modified`,
//!   `userPermissions`, `groupPermissions`) are accepted and skipped;
//! * scalars are coerced (numeric strings to numbers, numbers to strings, ...),
//!   `null` gives `null` or the Java primitive default;
//! * a JSON array deserialized into a `Set` drops elements that are `equals`
//!   to an earlier one. `equals` of the entities ignores `id`.
//!
//! Functions take a `base` value: a PUT applies the body to the loaded entity
//! (`readerForUpdating`), a POST starts from the constructor defaults.

use crate::model::*;
use chrono::NaiveDate;
use serde_json::{Map, Value};

pub type JRes<T> = Result<T, String>;

const IGNORED: &[&str] = &["created", "modified", "userPermissions", "groupPermissions"];

fn as_obj<'a>(v: &'a Value, what: &str) -> JRes<&'a Map<String, Value>> {
    v.as_object()
        .ok_or_else(|| format!("Cannot deserialize {what} from non-object value"))
}

/// Walks the keys of an object and dispatches the known ones.
/// `known` gives the accepted property names; ignored ones are skipped.
fn each_key<'a>(
    m: &'a Map<String, Value>,
    known: &[&str],
    mut f: impl FnMut(&str, &'a Value) -> JRes<()>,
) -> JRes<()> {
    for (k, v) in m {
        if known.contains(&k.as_str()) {
            f(k, v)?;
        } else if IGNORED.contains(&k.as_str()) {
            continue;
        } else {
            return Err(format!("Unrecognized field \"{k}\""));
        }
    }
    Ok(())
}

// ---- scalar coercions -------------------------------------------------------

pub fn str_opt(v: &Value) -> JRes<Option<String>> {
    Ok(match v {
        Value::Null => None,
        Value::String(s) => Some(s.clone()),
        Value::Number(n) => Some(n.to_string()),
        Value::Bool(b) => Some(b.to_string()),
        _ => return Err("Cannot deserialize String from object/array".into()),
    })
}

fn parse_i32(s: &str) -> JRes<i32> {
    let t = s.trim();
    t.parse::<i32>()
        .map_err(|_| format!("Cannot deserialize value of type int from String \"{s}\""))
}

pub fn int_opt(v: &Value) -> JRes<Option<i32>> {
    Ok(match v {
        Value::Null => None,
        Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                Some(i32::try_from(i).map_err(|_| "Numeric value out of range".to_string())?)
            } else {
                let f = n.as_f64().unwrap_or(0.0);
                if f.is_finite() && f.abs() <= i32::MAX as f64 {
                    Some(f.trunc() as i32)
                } else {
                    return Err("Numeric value out of range".into());
                }
            }
        }
        Value::String(s) => {
            if s.trim().is_empty() {
                None
            } else {
                Some(parse_i32(s)?)
            }
        }
        _ => return Err("Cannot deserialize value of type Integer".into()),
    })
}

/// Java primitive `int`: `null` gives 0.
pub fn int_prim(v: &Value) -> JRes<i32> {
    Ok(int_opt(v)?.unwrap_or(0))
}

pub fn f64_opt(v: &Value) -> JRes<Option<f64>> {
    Ok(match v {
        Value::Null => None,
        Value::Number(n) => Some(n.as_f64().unwrap_or(0.0)),
        Value::String(s) => {
            if s.trim().is_empty() {
                None
            } else {
                Some(
                    s.trim()
                        .parse::<f64>()
                        .map_err(|_| format!("Cannot deserialize value of type Double from String \"{s}\""))?,
                )
            }
        }
        _ => return Err("Cannot deserialize value of type Double".into()),
    })
}

pub fn bool_opt(v: &Value) -> JRes<Option<bool>> {
    Ok(match v {
        Value::Null => None,
        Value::Bool(b) => Some(*b),
        Value::Number(n) => Some(n.as_f64().unwrap_or(0.0) != 0.0),
        Value::String(s) => {
            let t = s.trim().to_ascii_lowercase();
            if t.is_empty() {
                None
            } else if t == "true" {
                Some(true)
            } else if t == "false" {
                Some(false)
            } else {
                return Err(format!("Cannot deserialize value of type Boolean from String \"{s}\""));
            }
        }
        _ => return Err("Cannot deserialize value of type Boolean".into()),
    })
}

/// Java primitive `boolean`: `null` gives false.
pub fn bool_prim(v: &Value) -> JRes<bool> {
    Ok(bool_opt(v)?.unwrap_or(false))
}

pub fn date_opt(v: &Value) -> JRes<Option<NaiveDate>> {
    Ok(match v {
        Value::Null => None,
        Value::String(s) if s.trim().is_empty() => None,
        Value::String(s) => Some(
            NaiveDate::parse_from_str(s.trim(), "%Y-%m-%d")
                .map_err(|_| format!("Invalid format: \"{s}\""))?,
        ),
        _ => return Err("Cannot deserialize value of type LocalDate".into()),
    })
}

/// `java.util.Locale` as Jackson reads it: `language_COUNTRY`, the same text as
/// `Locale.toString()` gives back.
pub fn locale_opt(v: &Value) -> JRes<Option<String>> {
    Ok(match v {
        Value::Null => None,
        Value::String(s) if s.is_empty() => None,
        Value::String(s) => {
            let mut parts = s.splitn(3, '_');
            let lang = parts.next().unwrap_or("").to_ascii_lowercase();
            let country = parts.next().map(|c| c.to_ascii_uppercase());
            let variant = parts.next();
            let mut out = lang;
            if let Some(c) = country {
                if !c.is_empty() || variant.is_some() {
                    out.push('_');
                    out.push_str(&c);
                }
            }
            if let Some(var) = variant {
                out.push('_');
                out.push_str(var);
            }
            Some(out)
        }
        _ => return Err("Cannot deserialize value of type Locale".into()),
    })
}

fn point_opt(v: &Value) -> JRes<Option<Point>> {
    if v.is_null() {
        return Ok(None);
    }
    let m = as_obj(v, "Point2D.Double")?;
    let mut p = Point::default();
    each_key(m, &["x", "y"], |k, v| {
        let f = f64_opt(v)?.unwrap_or(0.0);
        if k == "x" {
            p.x = f
        } else {
            p.y = f
        }
        Ok(())
    })?;
    Ok(Some(p))
}

fn array<'a>(v: &'a Value, what: &str) -> JRes<Option<&'a Vec<Value>>> {
    match v {
        Value::Null => Ok(None),
        Value::Array(a) => Ok(Some(a)),
        _ => Err(format!("Cannot deserialize {what} from non-array value")),
    }
}

// ---- equality used when a JSON array becomes a Set --------------------------

fn role_eq(a: &Role, b: &Role) -> bool {
    a.name == b.name && a.description == b.description
}

fn user_eq(a: &User, b: &User) -> bool {
    a.first_name == b.first_name
        && a.last_name == b.last_name
        && a.email == b.email
        && a.birthday == b.birthday
        && a.language == b.language
        && a.account_name == b.account_name
        && a.password == b.password
        && a.active == b.active
}

fn dedupe<T>(items: Vec<T>, eq: impl Fn(&T, &T) -> bool) -> Vec<T> {
    let mut out: Vec<T> = Vec::with_capacity(items.len());
    for it in items {
        if !out.iter().any(|o| eq(o, &it)) {
            out.push(it);
        }
    }
    out
}

// ---- entities ------------------------------------------------------------------

pub fn role(v: &Value, mut base: Role) -> JRes<Role> {
    let m = as_obj(v, "Role")?;
    each_key(m, &["id", "name", "description"], |k, v| {
        match k {
            "id" => base.id = int_opt(v)?,
            "name" => base.name = str_opt(v)?,
            _ => base.description = str_opt(v)?,
        }
        Ok(())
    })?;
    Ok(base)
}

pub fn user(v: &Value, mut base: User) -> JRes<User> {
    let m = as_obj(v, "User")?;
    each_key(
        m,
        &[
            "id", "firstName", "lastName", "email", "birthday", "language", "accountName",
            "password", "active", "roles", "userGroups",
        ],
        |k, v| {
            match k {
                "id" => base.id = int_opt(v)?,
                "firstName" => base.first_name = str_opt(v)?,
                "lastName" => base.last_name = str_opt(v)?,
                "email" => base.email = str_opt(v)?,
                "birthday" => base.birthday = date_opt(v)?,
                "language" => base.language = locale_opt(v)?,
                "accountName" => base.account_name = str_opt(v)?,
                "password" => base.password = str_opt(v)?,
                "active" => base.active = bool_prim(v)?,
                "roles" => {
                    base.roles = match array(v, "Set<Role>")? {
                        None => Vec::new(),
                        Some(a) => {
                            let mut items = Vec::new();
                            for e in a {
                                items.push(role(e, Role::default())?);
                            }
                            dedupe(items, role_eq)
                        }
                    }
                }
                _ => {
                    base.user_groups = match array(v, "Set<UserGroup>")? {
                        None => Vec::new(),
                        Some(a) => {
                            let mut ids: Vec<i32> = Vec::new();
                            for e in a {
                                let id = match e {
                                    Value::Number(_) => int_opt(e)?,
                                    Value::Object(o) => match o.get("id") {
                                        Some(idv) => int_opt(idv)?,
                                        None => None,
                                    },
                                    _ => return Err("Cannot resolve UserGroup id".into()),
                                };
                                let id = id.ok_or("Cannot persist a transient UserGroup")?;
                                if !ids.contains(&id) {
                                    ids.push(id);
                                }
                            }
                            ids
                        }
                    }
                }
            }
            Ok(())
        },
    )?;
    Ok(base)
}

pub fn group(v: &Value, mut base: Group) -> JRes<Group> {
    let m = as_obj(v, "UserGroup")?;
    each_key(m, &["id", "name", "owner", "members", "roles"], |k, v| {
        match k {
            "id" => base.id = int_opt(v)?,
            "name" => base.name = str_opt(v)?,
            "owner" => {
                base.owner = if v.is_null() {
                    None
                } else {
                    Some(Box::new(user(v, User::default())?))
                }
            }
            "members" => {
                base.members = match array(v, "Set<User>")? {
                    None => Vec::new(),
                    Some(a) => {
                        let mut items = Vec::new();
                        for e in a {
                            items.push(user(e, User::default())?);
                        }
                        dedupe(items, user_eq)
                    }
                }
            }
            _ => {
                base.roles = match array(v, "Set<Role>")? {
                    None => Vec::new(),
                    Some(a) => {
                        let mut items = Vec::new();
                        for e in a {
                            items.push(role(e, Role::default())?);
                        }
                        dedupe(items, role_eq)
                    }
                }
            }
        }
        Ok(())
    })?;
    Ok(base)
}

pub fn extent(v: &Value, mut base: Extent) -> JRes<Extent> {
    let m = as_obj(v, "Extent")?;
    each_key(m, &["id", "lowerLeft", "upperRight"], |k, v| {
        match k {
            "id" => base.id = int_opt(v)?,
            "lowerLeft" => base.lower_left = point_opt(v)?,
            _ => base.upper_right = point_opt(v)?,
        }
        Ok(())
    })?;
    Ok(base)
}

fn extent_opt(v: &Value) -> JRes<Option<Extent>> {
    if v.is_null() {
        Ok(None)
    } else {
        Ok(Some(extent(v, Extent::default())?))
    }
}

pub fn tile_grid(v: &Value, mut base: TileGrid) -> JRes<TileGrid> {
    let m = as_obj(v, "TileGrid")?;
    let mut known = vec!["id", "type", "tileGridOrigin", "tileGridExtent", "tileSize", "tileGridResolutions"];
    if base.wmts {
        known.push("matrixIds");
    }
    each_key(m, &known, |k, v| {
        match k {
            "id" => base.id = int_opt(v)?,
            "type" => base.type_ = str_opt(v)?,
            "tileGridOrigin" => base.origin = point_opt(v)?,
            "tileGridExtent" => base.extent = extent_opt(v)?,
            "tileSize" => base.tile_size = int_opt(v)?,
            "tileGridResolutions" => {
                base.resolutions = match array(v, "List<Double>")? {
                    None => None,
                    Some(a) => Some(a.iter().map(|e| f64_opt(e).map(|o| o.unwrap_or(0.0))).collect::<JRes<Vec<f64>>>()?),
                }
            }
            _ => {
                base.matrix_ids = match array(v, "List<String>")? {
                    None => None,
                    Some(a) => Some(a.iter().map(|e| str_opt(e).map(|o| o.unwrap_or_default())).collect::<JRes<Vec<String>>>()?),
                }
            }
        }
        Ok(())
    })?;
    Ok(base)
}

fn tile_grid_opt(v: &Value, wmts: bool) -> JRes<Option<TileGrid>> {
    if v.is_null() {
        return Ok(None);
    }
    let base = TileGrid { wmts, ..TileGrid::default() };
    Ok(Some(tile_grid(v, base)?))
}

pub fn appearance(v: &Value, mut base: Appearance) -> JRes<Appearance> {
    let m = as_obj(v, "LayerAppearance")?;
    each_key(
        m,
        &[
            "id", "attribution", "hoverable", "clickable", "hoverTemplate", "properties", "name",
            "maxResolution", "minResolution", "opacity", "visible",
        ],
        |k, v| {
            match k {
                "id" => base.id = int_opt(v)?,
                "attribution" => base.attribution = str_opt(v)?,
                "hoverable" => base.hoverable = bool_opt(v)?,
                "clickable" => base.clickable = bool_opt(v)?,
                "hoverTemplate" => base.hover_template = str_opt(v)?,
                "properties" => {
                    base.properties = match v {
                        Value::Null => None,
                        Value::Object(o) => Some(o.iter().map(|(k, v)| (k.clone(), v.clone())).collect()),
                        _ => return Err("Cannot deserialize Map".into()),
                    }
                }
                "name" => base.name = str_opt(v)?,
                "maxResolution" => base.max_resolution = f64_opt(v)?,
                "minResolution" => base.min_resolution = f64_opt(v)?,
                "opacity" => base.opacity = f64_opt(v)?,
                _ => base.visible = bool_opt(v)?,
            }
            Ok(())
        },
    )?;
    Ok(base)
}

pub fn layer(v: &Value, mut base: Layer) -> JRes<Layer> {
    let m = as_obj(v, "Layer")?;
    each_key(m, &["id", "name", "description", "source", "appearance"], |k, v| {
        match k {
            "id" => base.id = int_opt(v)?,
            "name" => base.name = str_opt(v)?,
            "description" => base.description = str_opt(v)?,
            "source" => {
                if v.is_null() {
                    base.source = None
                } else {
                    // `LayerDataSource` is abstract and has no type information:
                    // Jackson cannot construct it.
                    return Err("Cannot construct instance of LayerDataSource (abstract)".into());
                }
            }
            _ => {
                base.appearance = if v.is_null() {
                    None
                } else {
                    Some(appearance(v, Appearance::default())?)
                }
            }
        }
        Ok(())
    })?;
    Ok(base)
}

/// Applies a body to an existing data source (the runtime subclass decides the
/// accepted properties). Creating a data source is refused by the caller.
pub fn data_source(v: &Value, mut base: DataSource) -> JRes<DataSource> {
    let m = as_obj(v, "LayerDataSource")?;
    let mut known: Vec<&str> = vec!["id", "name", "type", "url", "format"];
    match base.kind {
        SourceKind::ImageWms(_) => known.extend([
            "width", "height", "version", "layerNames", "layerStyles", "requestableByPath", "customRequestPath",
        ]),
        SourceKind::TileWms(_) => known.extend([
            "width", "height", "version", "layerNames", "layerStyles", "requestableByPath", "customRequestPath",
            "tileGrid", "requestWithTiled",
        ]),
        SourceKind::Wfs(_) => known.extend(["version", "typeName", "typeNames"]),
        SourceKind::Wmts(_) => known.extend([
            "tileGrid", "urls", "wmtsLayer", "wmtsStyle", "projection", "matrixSet", "requestEncoding",
            "capabilitiesUrl",
        ]),
        SourceKind::Xyz(_) => known.extend(["center", "extent", "resolutions", "tileSize"]),
    }
    each_key(m, &known, |k, v| {
        match k {
            "id" => base.id = int_opt(v)?,
            "name" => base.name = str_opt(v)?,
            "type" => base.type_ = str_opt(v)?,
            "url" => base.url = str_opt(v)?,
            "format" => base.format = str_opt(v)?,
            _ => {}
        }
        match &mut base.kind {
            SourceKind::ImageWms(i) => image_field(i, k, v)?,
            SourceKind::TileWms(t) => match k {
                "tileGrid" => t.tile_grid = tile_grid_opt(v, false)?,
                "requestWithTiled" => t.request_with_tiled = bool_opt(v)?,
                _ => image_field(&mut t.image, k, v)?,
            },
            SourceKind::Wfs(w) => match k {
                "version" => w.version = str_opt(v)?,
                "typeName" => w.type_name = str_opt(v)?,
                "typeNames" => w.type_names = str_opt(v)?,
                _ => {}
            },
            SourceKind::Wmts(w) => match k {
                "tileGrid" => w.tile_grid = tile_grid_opt(v, true)?,
                "urls" => {
                    w.urls = match array(v, "List<String>")? {
                        None => None,
                        Some(a) => Some(a.iter().map(|e| str_opt(e).map(|o| o.unwrap_or_default())).collect::<JRes<Vec<String>>>()?),
                    }
                }
                "wmtsLayer" => w.wmts_layer = str_opt(v)?,
                "wmtsStyle" => w.wmts_style = str_opt(v)?,
                "projection" => w.projection = str_opt(v)?,
                "matrixSet" => w.matrix_set = str_opt(v)?,
                "requestEncoding" => w.request_encoding = str_opt(v)?,
                "capabilitiesUrl" => w.capabilities_url = str_opt(v)?,
                _ => {}
            },
            SourceKind::Xyz(x) => match k {
                "center" => x.center = point_opt(v)?,
                "extent" => x.extent = extent_opt(v)?,
                "resolutions" => {
                    x.resolutions = match array(v, "List<Double>")? {
                        None => Vec::new(),
                        Some(a) => a.iter().map(|e| f64_opt(e).map(|o| o.unwrap_or(0.0))).collect::<JRes<Vec<f64>>>()?,
                    }
                }
                "tileSize" => x.tile_size = int_opt(v)?,
                _ => {}
            },
        }
        Ok(())
    })?;
    Ok(base)
}

fn image_field(i: &mut ImageWms, k: &str, v: &Value) -> JRes<()> {
    match k {
        "width" => i.width = int_prim(v)?,
        "height" => i.height = int_prim(v)?,
        "version" => i.version = str_opt(v)?,
        "layerNames" => i.layer_names = str_opt(v)?,
        "layerStyles" => i.layer_styles = str_opt(v)?,
        "requestableByPath" => i.requestable_by_path = bool_opt(v)?,
        "customRequestPath" => i.custom_request_path = str_opt(v)?,
        _ => {}
    }
    Ok(())
}

