//! JSON of the entities, as Jackson writes the getters of the Java classes.
//! Null fields are written as `null`, collections as arrays, `password` is
//! write-only and `created`/`modified` are ignored.

use crate::model::*;
use serde_json::{json, Map, Value};

fn opt_str(v: &Option<String>) -> Value {
    match v {
        Some(s) => Value::String(s.clone()),
        None => Value::Null,
    }
}

fn opt_i32(v: Option<i32>) -> Value {
    match v {
        Some(i) => json!(i),
        None => Value::Null,
    }
}

fn opt_bool(v: Option<bool>) -> Value {
    match v {
        Some(b) => json!(b),
        None => Value::Null,
    }
}

fn opt_f64(v: Option<f64>) -> Value {
    match v {
        Some(f) => json_f64(f),
        None => Value::Null,
    }
}

pub fn json_f64(f: f64) -> Value {
    if f.is_finite() {
        serde_json::Number::from_f64(f).map(Value::Number).unwrap_or(Value::Null)
    } else {
        Value::Null
    }
}

pub fn point(p: &Option<Point>) -> Value {
    match p {
        Some(p) => json!({ "x": json_f64(p.x), "y": json_f64(p.y) }),
        None => Value::Null,
    }
}

pub fn extent(e: &Option<Extent>) -> Value {
    match e {
        Some(e) => json!({
            "id": opt_i32(e.id),
            "lowerLeft": point(&e.lower_left),
            "upperRight": point(&e.upper_right),
        }),
        None => Value::Null,
    }
}

pub fn tile_grid(t: &Option<TileGrid>) -> Value {
    match t {
        None => Value::Null,
        Some(t) => {
            let mut m = Map::new();
            m.insert("id".into(), opt_i32(t.id));
            m.insert("type".into(), opt_str(&t.type_));
            m.insert("tileGridOrigin".into(), point(&t.origin));
            m.insert("tileGridExtent".into(), extent(&t.extent));
            m.insert("tileSize".into(), opt_i32(t.tile_size));
            m.insert(
                "tileGridResolutions".into(),
                match &t.resolutions {
                    Some(r) => Value::Array(r.iter().map(|f| json_f64(*f)).collect()),
                    None => Value::Null,
                },
            );
            if t.wmts {
                m.insert(
                    "matrixIds".into(),
                    match &t.matrix_ids {
                        Some(ids) => Value::Array(ids.iter().map(|s| Value::String(s.clone())).collect()),
                        None => Value::Null,
                    },
                );
            }
            Value::Object(m)
        }
    }
}

pub fn role(r: &Role) -> Value {
    json!({ "id": opt_i32(r.id), "name": opt_str(&r.name), "description": opt_str(&r.description) })
}

pub fn user(u: &User) -> Value {
    json!({
        "id": opt_i32(u.id),
        "firstName": opt_str(&u.first_name),
        "lastName": opt_str(&u.last_name),
        "email": opt_str(&u.email),
        "birthday": match u.birthday {
            Some(d) => Value::String(d.format("%Y-%m-%d").to_string()),
            None => Value::Null,
        },
        "language": opt_str(&u.language),
        "accountName": opt_str(&u.account_name),
        "active": u.active,
        "roles": Value::Array(u.roles.iter().map(role).collect()),
        "userGroups": Value::Array(u.user_groups.iter().map(|i| json!(i)).collect()),
    })
}

pub fn group(g: &Group) -> Value {
    json!({
        "id": opt_i32(g.id),
        "name": opt_str(&g.name),
        "owner": match &g.owner {
            Some(o) => user(o),
            None => Value::Null,
        },
        "members": Value::Array(g.members.iter().map(user).collect()),
        "roles": Value::Array(g.roles.iter().map(role).collect()),
    })
}

pub fn appearance(a: &Appearance) -> Value {
    let props = match &a.properties {
        Some(p) => {
            let mut m = Map::new();
            for (k, v) in p {
                m.insert(k.clone(), v.clone());
            }
            Value::Object(m)
        }
        None => Value::Null,
    };
    json!({
        "id": opt_i32(a.id),
        "attribution": opt_str(&a.attribution),
        "hoverable": opt_bool(a.hoverable),
        "clickable": opt_bool(a.clickable),
        "hoverTemplate": opt_str(&a.hover_template),
        "properties": props,
        "name": opt_str(&a.name),
        "maxResolution": opt_f64(a.max_resolution),
        "minResolution": opt_f64(a.min_resolution),
        "opacity": opt_f64(a.opacity),
        "visible": opt_bool(a.visible),
    })
}

fn image_fields(m: &mut Map<String, Value>, i: &ImageWms) {
    m.insert("width".into(), json!(i.width));
    m.insert("height".into(), json!(i.height));
    m.insert("version".into(), opt_str(&i.version));
    m.insert("layerNames".into(), opt_str(&i.layer_names));
    m.insert("layerStyles".into(), opt_str(&i.layer_styles));
    m.insert("requestableByPath".into(), opt_bool(i.requestable_by_path));
    m.insert("customRequestPath".into(), opt_str(&i.custom_request_path));
}

pub fn source(s: &DataSource) -> Value {
    let mut m = Map::new();
    m.insert("id".into(), opt_i32(s.id));
    m.insert("name".into(), opt_str(&s.name));
    m.insert("type".into(), opt_str(&s.type_));
    m.insert("url".into(), opt_str(&s.url));
    m.insert("format".into(), opt_str(&s.format));
    match &s.kind {
        SourceKind::ImageWms(i) => image_fields(&mut m, i),
        SourceKind::TileWms(t) => {
            image_fields(&mut m, &t.image);
            m.insert("tileGrid".into(), tile_grid(&t.tile_grid));
            m.insert("requestWithTiled".into(), opt_bool(t.request_with_tiled));
        }
        SourceKind::Wfs(w) => {
            m.insert("version".into(), opt_str(&w.version));
            m.insert("typeName".into(), opt_str(&w.type_name));
            m.insert("typeNames".into(), opt_str(&w.type_names));
        }
        SourceKind::Wmts(w) => {
            m.insert("tileGrid".into(), tile_grid(&w.tile_grid));
            m.insert(
                "urls".into(),
                match &w.urls {
                    Some(u) => Value::Array(u.iter().map(|s| Value::String(s.clone())).collect()),
                    None => Value::Null,
                },
            );
            m.insert("wmtsLayer".into(), opt_str(&w.wmts_layer));
            m.insert("wmtsStyle".into(), opt_str(&w.wmts_style));
            m.insert("projection".into(), opt_str(&w.projection));
            m.insert("matrixSet".into(), opt_str(&w.matrix_set));
            m.insert("requestEncoding".into(), opt_str(&w.request_encoding));
            m.insert("capabilitiesUrl".into(), opt_str(&w.capabilities_url));
        }
        SourceKind::Xyz(x) => {
            m.insert("center".into(), point(&x.center));
            m.insert("extent".into(), extent(&x.extent));
            m.insert(
                "resolutions".into(),
                Value::Array(x.resolutions.iter().map(|f| json_f64(*f)).collect()),
            );
            m.insert("tileSize".into(), opt_i32(x.tile_size));
        }
    }
    Value::Object(m)
}

pub fn layer(l: &Layer) -> Value {
    json!({
        "id": opt_i32(l.id),
        "name": opt_str(&l.name),
        "description": opt_str(&l.description),
        "source": match &l.source {
            Some(s) => source(s),
            None => Value::Null,
        },
        "appearance": match &l.appearance {
            Some(a) => appearance(a),
            None => Value::Null,
        },
    })
}

