//! Database access: loading entities with their related rows, and saving them
//! as Hibernate would for the mapping of shogun-core on the schema of
//! `schema.sql` (JOINED inheritance for persons/users, layers and data
//! sources; ids from the `hibernate_sequences` table).

use crate::model::*;
use sqlx::postgres::PgRow;
use sqlx::pool::PoolConnection;
use sqlx::{PgConnection, Postgres, Row, Transaction};
use std::collections::{HashMap, HashSet};

pub type DbRes<T> = Result<T, String>;

fn e<E: std::fmt::Display>(err: E) -> String {
    err.to_string()
}

/// One request's database work: a transaction (committed on success) and a
/// separate connection for id allocation (Hibernate's table generator works
/// in its own transaction, so ids are consumed even if the request fails).
pub struct Ctx {
    pub tx: Transaction<'static, Postgres>,
    pub ids: PoolConnection<Postgres>,
    /// Entities that the Hibernate session of the request has loaded already.
    /// Saving a detached object with one of these ids through a cascade is a
    /// `NonUniqueObjectException` in the original.
    pub loaded: HashSet<(&'static str, i32)>,
}

impl Ctx {
    pub fn c(&mut self) -> &mut PgConnection {
        &mut self.tx
    }

    pub async fn alloc_id(&mut self) -> DbRes<i32> {
        // Hibernate's TableGenerator (default segment, allocation size 1):
        // new id = next_val + 1, and next_val becomes the new id.
        let v: i64 = sqlx::query_scalar(
            "UPDATE hibernate_sequences SET next_val = next_val + 1 \
             WHERE sequence_name = 'default' RETURNING next_val",
        )
        .fetch_one(&mut *self.ids)
        .await
        .map_err(e)?;
        i32::try_from(v).map_err(|_| "id out of range".to_string())
    }

    pub async fn exec(&mut self, sql: &str, binds: Vec<Bind>) -> DbRes<u64> {
        let mut q = sqlx::query(sql);
        for b in binds {
            q = b.bind(q);
        }
        let r = q.execute(&mut *self.tx).await.map_err(e)?;
        Ok(r.rows_affected())
    }

    /// Updates a row that must exist (Hibernate's StaleStateException otherwise).
    pub async fn update_one(&mut self, sql: &str, binds: Vec<Bind>) -> DbRes<()> {
        let n = self.exec(sql, binds).await?;
        if n != 1 {
            return Err("Row was updated or deleted by another transaction".into());
        }
        Ok(())
    }
}

/// Values bound to the statements.
#[derive(Clone)]
pub enum Bind {
    I(Option<i32>),
    F(Option<f64>),
    B(Option<bool>),
    S(Option<String>),
    D(Option<chrono::NaiveDate>),
    Bytes(Vec<u8>),
}

impl Bind {
    fn bind<'q>(self, q: sqlx::query::Query<'q, Postgres, sqlx::postgres::PgArguments>) -> sqlx::query::Query<'q, Postgres, sqlx::postgres::PgArguments> {
        match self {
            Bind::I(v) => q.bind(v),
            Bind::F(v) => q.bind(v),
            Bind::B(v) => q.bind(v),
            Bind::S(v) => q.bind(v),
            Bind::D(v) => q.bind(v),
            Bind::Bytes(v) => q.bind(v),
        }
    }
}

pub fn bi(v: Option<i32>) -> Bind {
    Bind::I(v)
}
pub fn bs(v: &Option<String>) -> Bind {
    Bind::S(v.clone())
}

// ---------------------------------------------------------------------------
// Loading
// ---------------------------------------------------------------------------

fn ids_filter(ids: &Option<Vec<i32>>) -> Option<Vec<i32>> {
    ids.clone()
}

async fn fetch(cx: &mut Ctx, sql: &str, ids: &Option<Vec<i32>>) -> DbRes<Vec<PgRow>> {
    let rows = match ids_filter(ids) {
        None => sqlx::query(sql).fetch_all(&mut *cx.tx).await,
        Some(v) => sqlx::query(&format!("{sql} WHERE id = ANY($1)")).bind(v).fetch_all(&mut *cx.tx).await,
    };
    rows.map_err(e)
}

fn point_from(x: Option<f64>, y: Option<f64>) -> Option<Point> {
    if x.is_none() && y.is_none() {
        None
    } else {
        Some(Point { x: x.unwrap_or(0.0), y: y.unwrap_or(0.0) })
    }
}

pub async fn load_roles(cx: &mut Ctx, ids: Option<Vec<i32>>) -> DbRes<HashMap<i32, Role>> {
    let rows = fetch(cx, "SELECT id, name, description FROM roles", &ids).await?;
    let mut out = HashMap::new();
    for r in rows {
        let id: i32 = r.get("id");
        out.insert(
            id,
            Role {
                id: Some(id),
                name: r.get("name"),
                description: r.get("description"),
            },
        );
    }
    Ok(out)
}

/// Users with their roles and the ids of their groups.
pub async fn load_users(cx: &mut Ctx, ids: Option<Vec<i32>>) -> DbRes<HashMap<i32, User>> {
    let mut users: HashMap<i32, User> = HashMap::new();
    let rows = match &ids {
        None => sqlx::query(
            "SELECT p.id, p.firstname, p.lastname, p.email, p.birthday, p.language, \
             u.accountname, u.password, u.active FROM users u JOIN persons p ON p.id = u.id ORDER BY u.id",
        )
        .fetch_all(&mut *cx.tx)
        .await,
        Some(v) => sqlx::query(
            "SELECT p.id, p.firstname, p.lastname, p.email, p.birthday, p.language, \
             u.accountname, u.password, u.active FROM users u JOIN persons p ON p.id = u.id WHERE u.id = ANY($1)",
        )
        .bind(v.clone())
        .fetch_all(&mut *cx.tx)
        .await,
    }
    .map_err(e)?;
    for r in rows {
        let id: i32 = r.get("id");
        users.insert(
            id,
            User {
                id: Some(id),
                first_name: r.get("firstname"),
                last_name: r.get("lastname"),
                email: r.get("email"),
                birthday: r.get("birthday"),
                language: r.get("language"),
                account_name: r.get("accountname"),
                password: r.get("password"),
                active: r.get::<Option<bool>, _>("active").unwrap_or(false),
                roles: Vec::new(),
                user_groups: Vec::new(),
            },
        );
    }
    if users.is_empty() {
        return Ok(users);
    }
    let user_ids: Vec<i32> = users.keys().copied().collect();
    let roles = sqlx::query("SELECT user_id, role_id FROM users_roles WHERE user_id = ANY($1) ORDER BY role_id")
        .bind(user_ids.clone())
        .fetch_all(&mut *cx.tx)
        .await
        .map_err(e)?;
    let role_ids: Vec<i32> = roles.iter().map(|r| r.get::<i32, _>("role_id")).collect();
    let role_map = if role_ids.is_empty() { HashMap::new() } else { load_roles(cx, Some(role_ids)).await? };
    for r in roles {
        let uid: i32 = r.get("user_id");
        let rid: i32 = r.get("role_id");
        if let (Some(u), Some(role)) = (users.get_mut(&uid), role_map.get(&rid)) {
            u.roles.push(role.clone());
        }
    }
    let groups = sqlx::query("SELECT user_id, usergroup_id FROM user_usergroup WHERE user_id = ANY($1) ORDER BY usergroup_id")
        .bind(user_ids)
        .fetch_all(&mut *cx.tx)
        .await
        .map_err(e)?;
    for g in groups {
        let uid: i32 = g.get("user_id");
        if let Some(u) = users.get_mut(&uid) {
            u.user_groups.push(g.get("usergroup_id"));
        }
    }
    Ok(users)
}

pub async fn load_user(cx: &mut Ctx, id: i32) -> DbRes<Option<User>> {
    Ok(load_users(cx, Some(vec![id])).await?.remove(&id))
}

/// Groups with owner, members and roles (members/owner loaded without their groups).
pub async fn load_groups(cx: &mut Ctx, ids: Option<Vec<i32>>) -> DbRes<Vec<Group>> {
    let rows = fetch(cx, "SELECT id, name, owner_id FROM usergroups", &ids).await?;
    let mut groups: Vec<(i32, Group, Option<i32>)> = Vec::new();
    for r in rows {
        let id: i32 = r.get("id");
        let owner: Option<i32> = r.get("owner_id");
        groups.push((
            id,
            Group { id: Some(id), name: r.get("name"), owner: None, members: Vec::new(), roles: Vec::new() },
            owner,
        ));
    }
    if groups.is_empty() {
        return Ok(vec![]);
    }
    let gids: Vec<i32> = groups.iter().map(|g| g.0).collect();
    let owner_ids: Vec<i32> = groups.iter().filter_map(|g| g.2).collect();
    let owners = if owner_ids.is_empty() { HashMap::new() } else { load_users(cx, Some(owner_ids)).await? };
    let members_rows = sqlx::query("SELECT usergroup_id, user_id FROM user_usergroup WHERE usergroup_id = ANY($1) ORDER BY user_id")
        .bind(gids.clone())
        .fetch_all(&mut *cx.tx)
        .await
        .map_err(e)?;
    let member_ids: Vec<i32> = members_rows.iter().map(|r| r.get::<i32, _>("user_id")).collect();
    let members = if member_ids.is_empty() { HashMap::new() } else { load_users(cx, Some(member_ids)).await? };
    let role_rows = sqlx::query("SELECT usergroup_id, role_id FROM usergroups_roles WHERE usergroup_id = ANY($1) ORDER BY role_id")
        .bind(gids)
        .fetch_all(&mut *cx.tx)
        .await
        .map_err(e)?;
    let role_ids: Vec<i32> = role_rows.iter().map(|r| r.get::<i32, _>("role_id")).collect();
    let roles = if role_ids.is_empty() { HashMap::new() } else { load_roles(cx, Some(role_ids)).await? };

    let mut out = Vec::new();
    for (id, mut g, owner) in groups {
        g.owner = owner.and_then(|o| owners.get(&o).cloned()).map(Box::new);
        for r in members_rows.iter().filter(|r| r.get::<i32, _>("usergroup_id") == id) {
            if let Some(u) = members.get(&r.get::<i32, _>("user_id")) {
                g.members.push(u.clone());
            }
        }
        for r in role_rows.iter().filter(|r| r.get::<i32, _>("usergroup_id") == id) {
            if let Some(role) = roles.get(&r.get::<i32, _>("role_id")) {
                g.roles.push(role.clone());
            }
        }
        out.push(g);
    }
    Ok(out)
}

pub async fn load_group(cx: &mut Ctx, id: i32) -> DbRes<Option<Group>> {
    Ok(load_groups(cx, Some(vec![id])).await?.pop())
}

fn load_point_pair(r: &PgRow, xcol: &str, ycol: &str) -> Option<Point> {
    point_from(r.get::<Option<f64>, _>(xcol), r.get::<Option<f64>, _>(ycol))
}

pub async fn load_extents(cx: &mut Ctx, ids: Option<Vec<i32>>) -> DbRes<HashMap<i32, Extent>> {
    let rows = fetch(
        cx,
        "SELECT id, lowerleft_x, lowerleft_y, upperright_x, upperright_y FROM extents",
        &ids,
    )
    .await?;
    let mut out = HashMap::new();
    for r in rows {
        let id: i32 = r.get("id");
        out.insert(
            id,
            Extent {
                id: Some(id),
                lower_left: point_from(r.get("lowerleft_x"), r.get("lowerleft_y")),
                upper_right: point_from(r.get("upperright_x"), r.get("upperright_y")),
            },
        );
    }
    Ok(out)
}

pub async fn load_tile_grids(cx: &mut Ctx, ids: Option<Vec<i32>>) -> DbRes<HashMap<i32, TileGrid>> {
    let rows = fetch(
        cx,
        "SELECT id, tilegridorigin_x, tilegridorigin_y, tilesize, type, tilegridextent_id FROM tilegrids",
        &ids,
    )
    .await?;
    let mut out: HashMap<i32, TileGrid> = HashMap::new();
    let mut extent_ids = Vec::new();
    for r in &rows {
        let id: i32 = r.get("id");
        let ext: Option<i32> = r.get("tilegridextent_id");
        if let Some(x) = ext {
            extent_ids.push(x);
        }
        out.insert(
            id,
            TileGrid {
                id: Some(id),
                type_: r.get("type"),
                origin: load_point_pair(r, "tilegridorigin_x", "tilegridorigin_y"),
                extent: None,
                tile_size: r.get("tilesize"),
                resolutions: Some(Vec::new()),
                wmts: false,
                matrix_ids: None,
            },
        );
    }
    if out.is_empty() {
        return Ok(out);
    }
    let keys: Vec<i32> = out.keys().copied().collect();
    let extents = if extent_ids.is_empty() { HashMap::new() } else { load_extents(cx, Some(extent_ids)).await? };
    for r in &rows {
        let id: i32 = r.get("id");
        let ext: Option<i32> = r.get("tilegridextent_id");
        if let (Some(t), Some(x)) = (out.get_mut(&id), ext) {
            t.extent = extents.get(&x).cloned();
        }
    }
    let wmts = sqlx::query("SELECT id FROM wmtstilegrids WHERE id = ANY($1)")
        .bind(keys.clone())
        .fetch_all(&mut *cx.tx)
        .await
        .map_err(e)?;
    for r in wmts {
        let id: i32 = r.get("id");
        if let Some(t) = out.get_mut(&id) {
            t.wmts = true;
            t.matrix_ids = Some(Vec::new());
        }
    }
    let mids = sqlx::query("SELECT wmtstilegrids_id, matrixids FROM wmtstilegrids_matrixids WHERE wmtstilegrids_id = ANY($1)")
        .bind(keys.clone())
        .fetch_all(&mut *cx.tx)
        .await
        .map_err(e)?;
    for r in mids {
        let id: i32 = r.get("wmtstilegrids_id");
        if let Some(t) = out.get_mut(&id) {
            t.matrix_ids.get_or_insert_with(Vec::new).push(r.get::<Option<String>, _>("matrixids").unwrap_or_default());
        }
    }
    let res = sqlx::query("SELECT tilegrid_id, resolution FROM tilegrid_resolution WHERE tilegrid_id = ANY($1) ORDER BY idx")
        .bind(keys)
        .fetch_all(&mut *cx.tx)
        .await
        .map_err(e)?;
    for r in res {
        let id: i32 = r.get("tilegrid_id");
        if let Some(t) = out.get_mut(&id) {
            t.resolutions.get_or_insert_with(Vec::new).push(r.get::<Option<f64>, _>("resolution").unwrap_or(0.0));
        }
    }
    Ok(out)
}

pub async fn load_appearances(cx: &mut Ctx, ids: Option<Vec<i32>>) -> DbRes<HashMap<i32, Appearance>> {
    let rows = fetch(
        cx,
        "SELECT id, attribution, clickable, hovertemplate, hoverable, maxresolution, minresolution, name, opacity, visible \
         FROM layerappearances",
        &ids,
    )
    .await?;
    let mut out = HashMap::new();
    for r in rows {
        let id: i32 = r.get("id");
        out.insert(
            id,
            Appearance {
                id: Some(id),
                attribution: r.get("attribution"),
                hoverable: r.get("hoverable"),
                clickable: r.get("clickable"),
                hover_template: r.get("hovertemplate"),
                properties: Some(Vec::new()),
                name: r.get("name"),
                max_resolution: r.get("maxresolution"),
                min_resolution: r.get("minresolution"),
                opacity: r.get("opacity"),
                visible: r.get("visible"),
            },
        );
    }
    if out.is_empty() {
        return Ok(out);
    }
    let keys: Vec<i32> = out.keys().copied().collect();
    let props = sqlx::query("SELECT appearance_id, property, value FROM layerappearances_properties WHERE appearance_id = ANY($1) ORDER BY property")
        .bind(keys)
        .fetch_all(&mut *cx.tx)
        .await
        .map_err(e)?;
    for r in props {
        let id: i32 = r.get("appearance_id");
        let key: String = r.get("property");
        let value: Option<String> = r.get("value");
        if let Some(a) = out.get_mut(&id) {
            a.properties
                .get_or_insert_with(Vec::new)
                .push((key, convert_property_value(value.as_deref().unwrap_or(""))));
        }
    }
    Ok(out)
}

/// `PropertyValueConverter.convertToEntityAttribute`.
pub fn convert_property_value(s: &str) -> serde_json::Value {
    use serde_json::Value;
    if s.eq_ignore_ascii_case("true") {
        return Value::Bool(true);
    }
    if s.eq_ignore_ascii_case("false") {
        return Value::Bool(false);
    }
    let digits = |t: &str| !t.is_empty() && t.bytes().all(|b| b.is_ascii_digit());
    if digits(s) || (s.starts_with('-') && digits(&s[1..])) {
        if let Ok(v) = s.parse::<i64>() {
            return Value::from(v);
        }
    }
    let parsable = {
        let t = s.strip_prefix('-').unwrap_or(s);
        !t.is_empty() && t.chars().filter(|c| *c == '.').count() <= 1 && t.chars().all(|c| c.is_ascii_digit() || c == '.') && t.chars().any(|c| c.is_ascii_digit())
    };
    if parsable {
        if let Ok(f) = s.parse::<f64>() {
            return crate::jout::json_f64(f);
        }
    }
    Value::String(s.to_string())
}

/// `PropertyValueConverter.convertToDatabaseColumn`: `Object.toString()`.
pub fn property_value_text(v: &serde_json::Value) -> DbRes<String> {
    use serde_json::Value;
    Ok(match v {
        Value::Null => return Err("property value is null".into()),
        Value::String(s) => s.clone(),
        Value::Bool(b) => b.to_string(),
        Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                i.to_string()
            } else {
                let f = n.as_f64().unwrap_or(0.0);
                java_double_text(f)
            }
        }
        _ => return Err("unsupported property value".into()),
    })
}

/// `Double.toString` for the common values.
pub fn java_double_text(f: f64) -> String {
    if f.fract() == 0.0 && f.abs() < 1e7 {
        format!("{:.1}", f)
    } else {
        format!("{}", f)
    }
}

/// The Java serialization of a `java.lang.Double` (as Hibernate's
/// SerializableType stores the XYZ resolutions): the stream header, the class
/// descriptors of Double and Number, and the 8 bytes of the value.
pub fn java_double_bytes(v: f64) -> Vec<u8> {
    let mut out: Vec<u8> = vec![
        0xAC, 0xED, 0x00, 0x05, // stream magic and version
        0x73, // TC_OBJECT
        0x72, // TC_CLASSDESC
        0x00, 0x10, // length of "java.lang.Double"
    ];
    out.extend_from_slice(b"java.lang.Double");
    out.extend_from_slice(&0x80B3_C24A_296B_FB04u64.to_be_bytes()); // serialVersionUID
    out.push(0x02); // SC_SERIALIZABLE
    out.extend_from_slice(&[0x00, 0x01]); // one field
    out.push(b'D'); // double
    out.extend_from_slice(&[0x00, 0x05]);
    out.extend_from_slice(b"value");
    out.push(0x78); // TC_ENDBLOCKDATA
    out.push(0x72); // TC_CLASSDESC java.lang.Number
    out.extend_from_slice(&[0x00, 0x10]);
    out.extend_from_slice(b"java.lang.Number");
    out.extend_from_slice(&(-8742448824652078965i64).to_be_bytes());
    out.push(0x02);
    out.extend_from_slice(&[0x00, 0x00]);
    out.push(0x78);
    out.push(0x70); // TC_NULL (no superclass of Number)
    out.extend_from_slice(&v.to_be_bytes());
    out
}

pub fn java_double_from_bytes(b: &[u8]) -> f64 {
    if b.len() < 8 {
        return 0.0;
    }
    let mut arr = [0u8; 8];
    arr.copy_from_slice(&b[b.len() - 8..]);
    f64::from_be_bytes(arr)
}

pub async fn load_sources(cx: &mut Ctx, ids: Option<Vec<i32>>) -> DbRes<HashMap<i32, DataSource>> {
    let rows = fetch(cx, "SELECT id, name, type, url, format FROM layerdatasources", &ids).await?;
    let mut base: HashMap<i32, DataSource> = HashMap::new();
    for r in rows {
        let id: i32 = r.get("id");
        base.insert(
            id,
            DataSource {
                id: Some(id),
                name: r.get("name"),
                type_: r.get("type"),
                url: r.get("url"),
                format: r.get("format"),
                kind: SourceKind::Wfs(Wfs::default()), // replaced below
            },
        );
    }
    if base.is_empty() {
        return Ok(base);
    }
    let keys: Vec<i32> = base.keys().copied().collect();
    let mut kinds: HashMap<i32, SourceKind> = HashMap::new();

    let image = sqlx::query(
        "SELECT id, width, height, version, layernames, layerstyles, requestablebypath, customrequestpath \
         FROM imagewmslayerdatasources WHERE id = ANY($1)",
    )
    .bind(keys.clone())
    .fetch_all(&mut *cx.tx)
    .await
    .map_err(e)?;
    let mut images: HashMap<i32, ImageWms> = HashMap::new();
    for r in &image {
        images.insert(
            r.get("id"),
            ImageWms {
                width: r.get("width"),
                height: r.get("height"),
                version: r.get("version"),
                layer_names: r.get("layernames"),
                layer_styles: r.get("layerstyles"),
                requestable_by_path: r.get("requestablebypath"),
                custom_request_path: r.get("customrequestpath"),
            },
        );
    }
    let tile = sqlx::query("SELECT id, request_with_tiled, tilegrid_id FROM tilewmslayerdatasources WHERE id = ANY($1)")
        .bind(keys.clone())
        .fetch_all(&mut *cx.tx)
        .await
        .map_err(e)?;
    let mut tile_grid_ids = Vec::new();
    let mut tiles: HashMap<i32, (Option<bool>, Option<i32>)> = HashMap::new();
    for r in &tile {
        let tg: Option<i32> = r.get("tilegrid_id");
        if let Some(t) = tg {
            tile_grid_ids.push(t);
        }
        tiles.insert(r.get("id"), (r.get("request_with_tiled"), tg));
    }
    let wfs = sqlx::query("SELECT id, typename, typenames, version FROM wfslayerdatasources WHERE id = ANY($1)")
        .bind(keys.clone())
        .fetch_all(&mut *cx.tx)
        .await
        .map_err(e)?;
    let wmts = sqlx::query(
        "SELECT id, capabilitiesurl, matrixset, projection, requestencoding, wmtslayer, wmtsstyle, tilegrid_id \
         FROM wmtslayerdatasources WHERE id = ANY($1)",
    )
    .bind(keys.clone())
    .fetch_all(&mut *cx.tx)
    .await
    .map_err(e)?;
    let mut wmts_grid_ids = Vec::new();
    for r in &wmts {
        if let Some(t) = r.get::<Option<i32>, _>("tilegrid_id") {
            wmts_grid_ids.push(t);
        }
    }
    let wmts_urls = sqlx::query("SELECT wmtslayerdatasources_id, urls FROM wmtslayerdatasources_urls WHERE wmtslayerdatasources_id = ANY($1)")
        .bind(keys.clone())
        .fetch_all(&mut *cx.tx)
        .await
        .map_err(e)?;
    let xyz = sqlx::query("SELECT id, center_x, center_y, tilesize, extent_id FROM xyzlayerdatasources WHERE id = ANY($1)")
        .bind(keys.clone())
        .fetch_all(&mut *cx.tx)
        .await
        .map_err(e)?;
    let mut xyz_extent_ids = Vec::new();
    for r in &xyz {
        if let Some(x) = r.get::<Option<i32>, _>("extent_id") {
            xyz_extent_ids.push(x);
        }
    }
    let xyz_res = sqlx::query("SELECT xyzlayerdatasrc_id, resolution FROM xyzlayerdatasrc_resolution WHERE xyzlayerdatasrc_id = ANY($1) ORDER BY idx")
        .bind(keys)
        .fetch_all(&mut *cx.tx)
        .await
        .map_err(e)?;

    let mut all_grid_ids = tile_grid_ids.clone();
    all_grid_ids.extend(wmts_grid_ids.iter().copied());
    let grids = if all_grid_ids.is_empty() { HashMap::new() } else { load_tile_grids(cx, Some(all_grid_ids)).await? };
    let extents = if xyz_extent_ids.is_empty() { HashMap::new() } else { load_extents(cx, Some(xyz_extent_ids)).await? };

    for r in &tile {
        let id: i32 = r.get("id");
        let (rwt, tg) = tiles[&id];
        let image = images.get(&id).cloned().unwrap_or_default();
        kinds.insert(
            id,
            SourceKind::TileWms(TileWms {
                image,
                tile_grid: tg.and_then(|t| grids.get(&t).cloned()),
                request_with_tiled: rwt,
            }),
        );
    }
    for (id, image) in &images {
        kinds.entry(*id).or_insert_with(|| SourceKind::ImageWms(image.clone()));
    }
    for r in &wfs {
        kinds.insert(
            r.get("id"),
            SourceKind::Wfs(Wfs {
                version: r.get("version"),
                type_name: r.get("typename"),
                type_names: r.get("typenames"),
            }),
        );
    }
    let mut urls: HashMap<i32, Vec<String>> = HashMap::new();
    for r in &wmts_urls {
        urls.entry(r.get("wmtslayerdatasources_id"))
            .or_default()
            .push(r.get::<Option<String>, _>("urls").unwrap_or_default());
    }
    for r in &wmts {
        let id: i32 = r.get("id");
        let grid = r.get::<Option<i32>, _>("tilegrid_id").and_then(|t| grids.get(&t).cloned());
        kinds.insert(
            id,
            SourceKind::Wmts(Wmts {
                tile_grid: grid,
                urls: Some(urls.remove(&id).unwrap_or_default()),
                wmts_layer: r.get("wmtslayer"),
                wmts_style: r.get("wmtsstyle"),
                projection: r.get("projection"),
                matrix_set: r.get("matrixset"),
                request_encoding: r.get("requestencoding"),
                capabilities_url: r.get("capabilitiesurl"),
            }),
        );
    }
    let mut xres: HashMap<i32, Vec<f64>> = HashMap::new();
    for r in &xyz_res {
        let b: Vec<u8> = r.get("resolution");
        xres.entry(r.get("xyzlayerdatasrc_id")).or_default().push(java_double_from_bytes(&b));
    }
    for r in &xyz {
        let id: i32 = r.get("id");
        kinds.insert(
            id,
            SourceKind::Xyz(Xyz {
                center: point_from(r.get("center_x"), r.get("center_y")),
                extent: r.get::<Option<i32>, _>("extent_id").and_then(|x| extents.get(&x).cloned()),
                resolutions: xres.remove(&id).unwrap_or_default(),
                tile_size: r.get("tilesize"),
            }),
        );
    }
    for (id, k) in kinds {
        if let Some(b) = base.get_mut(&id) {
            b.kind = k;
        }
    }
    base.retain(|_, s| !matches!(s.kind, SourceKind::Wfs(Wfs { version: None, type_name: None, type_names: None })) || true);
    Ok(base)
}

pub async fn load_layers(cx: &mut Ctx, ids: Option<Vec<i32>>) -> DbRes<Vec<Layer>> {
    let rows = fetch(cx, "SELECT id, name, description, appearance_id, source_id FROM layers", &ids).await?;
    let source_ids: Vec<i32> = rows.iter().filter_map(|r| r.get::<Option<i32>, _>("source_id")).collect();
    let app_ids: Vec<i32> = rows.iter().filter_map(|r| r.get::<Option<i32>, _>("appearance_id")).collect();
    let sources = if source_ids.is_empty() { HashMap::new() } else { load_sources(cx, Some(source_ids)).await? };
    let apps = if app_ids.is_empty() { HashMap::new() } else { load_appearances(cx, Some(app_ids)).await? };
    let mut out = Vec::new();
    for r in rows {
        let id: i32 = r.get("id");
        out.push(Layer {
            id: Some(id),
            name: r.get("name"),
            description: r.get("description"),
            source: r.get::<Option<i32>, _>("source_id").and_then(|s| sources.get(&s).cloned()),
            appearance: r.get::<Option<i32>, _>("appearance_id").and_then(|a| apps.get(&a).cloned()),
        });
    }
    Ok(out)
}

pub async fn load_layer(cx: &mut Ctx, id: i32) -> DbRes<Option<Layer>> {
    Ok(load_layers(cx, Some(vec![id])).await?.pop())
}

/// Ids of the user groups that the user belongs to (for the principal).
pub async fn user_group_ids(cx: &mut Ctx, user_id: i32) -> DbRes<HashSet<i32>> {
    let rows = sqlx::query("SELECT usergroup_id FROM user_usergroup WHERE user_id = $1")
        .bind(user_id)
        .fetch_all(&mut *cx.tx)
        .await
        .map_err(e)?;
    Ok(rows.iter().map(|r| r.get::<i32, _>("usergroup_id")).collect())
}

/// Role names granted to a user: its roles and the roles of its groups.
pub async fn authorities(cx: &mut Ctx, user_id: i32) -> DbRes<HashSet<String>> {
    let rows = sqlx::query(
        "SELECT r.name FROM users_roles ur JOIN roles r ON r.id = ur.role_id WHERE ur.user_id = $1 \
         UNION SELECT r.name FROM user_usergroup ug JOIN usergroups_roles gr ON gr.usergroup_id = ug.usergroup_id \
         JOIN roles r ON r.id = gr.role_id WHERE ug.user_id = $1",
    )
    .bind(user_id)
    .fetch_all(&mut *cx.tx)
    .await
    .map_err(e)?;
    Ok(rows.iter().filter_map(|r| r.get::<Option<String>, _>("name")).collect())
}

/// Finds the account for HTTP Basic: id, active flag, and password hash.
pub async fn account(cx: &mut Ctx, account_name: &str) -> DbRes<Option<(i32, bool, Option<String>)>> {
    let row = sqlx::query("SELECT id, active, password FROM users WHERE accountname = $1")
        .bind(account_name)
        .fetch_optional(&mut *cx.tx)
        .await
        .map_err(e)?;
    Ok(row.map(|r| {
        (
            r.get("id"),
            r.get::<Option<bool>, _>("active").unwrap_or(false),
            r.get("password"),
        )
    }))
}

// ---------------------------------------------------------------------------
// Saving (Hibernate's saveOrUpdate with the cascades of the mapping)
// ---------------------------------------------------------------------------

/// Saves a user: `persons` + `users` rows, and the `users_roles` and
/// `user_usergroup` join rows, which are replaced by the collections.
pub async fn save_user(cx: &mut Ctx, u: &mut User) -> DbRes<()> {
    match u.id {
        None => {
            let id = cx.alloc_id().await?;
            u.id = Some(id);
            cx.exec(
                "INSERT INTO persons (id, created, modified, birthday, email, firstname, language, lastname) \
                 VALUES ($1, now(), now(), $2, $3, $4, $5, $6)",
                vec![Bind::I(Some(id)), Bind::D(u.birthday), bs(&u.email), bs(&u.first_name), bs(&u.language), bs(&u.last_name)],
            )
            .await?;
            cx.exec(
                "INSERT INTO users (id, accountname, active, password) VALUES ($1, $2, $3, $4)",
                vec![Bind::I(Some(id)), bs(&u.account_name), Bind::B(Some(u.active)), bs(&u.password)],
            )
            .await?;
        }
        Some(id) => {
            cx.update_one(
                "UPDATE persons SET modified = now(), birthday = $2, email = $3, firstname = $4, language = $5, lastname = $6 WHERE id = $1",
                vec![Bind::I(Some(id)), Bind::D(u.birthday), bs(&u.email), bs(&u.first_name), bs(&u.language), bs(&u.last_name)],
            )
            .await?;
            cx.update_one(
                "UPDATE users SET accountname = $2, active = $3, password = $4 WHERE id = $1",
                vec![Bind::I(Some(id)), bs(&u.account_name), Bind::B(Some(u.active)), bs(&u.password)],
            )
            .await?;
        }
    }
    let id = u.id.unwrap_or_default();
    cx.exec("DELETE FROM users_roles WHERE user_id = $1", vec![Bind::I(Some(id))]).await?;
    for r in &u.roles {
        let rid = r.id.ok_or("object references an unsaved transient instance: Role")?;
        cx.exec(
            "INSERT INTO users_roles (user_id, role_id) VALUES ($1, $2)",
            vec![Bind::I(Some(id)), Bind::I(Some(rid))],
        )
        .await?;
    }
    cx.exec("DELETE FROM user_usergroup WHERE user_id = $1", vec![Bind::I(Some(id))]).await?;
    for g in &u.user_groups {
        cx.exec(
            "INSERT INTO user_usergroup (usergroup_id, user_id) VALUES ($1, $2)",
            vec![Bind::I(Some(*g)), Bind::I(Some(id))],
        )
        .await?;
    }
    Ok(())
}

pub async fn save_role(cx: &mut Ctx, r: &mut Role) -> DbRes<()> {
    match r.id {
        None => {
            let id = cx.alloc_id().await?;
            r.id = Some(id);
            cx.exec(
                "INSERT INTO roles (id, created, modified, description, name) VALUES ($1, now(), now(), $2, $3)",
                vec![Bind::I(Some(id)), bs(&r.description), bs(&r.name)],
            )
            .await?;
        }
        Some(id) => {
            cx.update_one(
                "UPDATE roles SET modified = now(), description = $2, name = $3 WHERE id = $1",
                vec![Bind::I(Some(id)), bs(&r.description), bs(&r.name)],
            )
            .await?;
        }
    }
    Ok(())
}

pub async fn save_group(cx: &mut Ctx, g: &mut Group) -> DbRes<()> {
    let owner_id = match &g.owner {
        None => None,
        Some(o) => Some(o.id.ok_or("object references an unsaved transient instance: User")?),
    };
    match g.id {
        None => {
            let id = cx.alloc_id().await?;
            g.id = Some(id);
            cx.exec(
                "INSERT INTO usergroups (id, created, modified, name, owner_id) VALUES ($1, now(), now(), $2, $3)",
                vec![Bind::I(Some(id)), bs(&g.name), Bind::I(owner_id)],
            )
            .await?;
        }
        Some(id) => {
            cx.update_one(
                "UPDATE usergroups SET modified = now(), name = $2, owner_id = $3 WHERE id = $1",
                vec![Bind::I(Some(id)), bs(&g.name), Bind::I(owner_id)],
            )
            .await?;
        }
    }
    let id = g.id.unwrap_or_default();
    cx.exec("DELETE FROM user_usergroup WHERE usergroup_id = $1", vec![Bind::I(Some(id))]).await?;
    for m in &g.members {
        let mid = m.id.ok_or("object references an unsaved transient instance: User")?;
        cx.exec(
            "INSERT INTO user_usergroup (usergroup_id, user_id) VALUES ($1, $2)",
            vec![Bind::I(Some(id)), Bind::I(Some(mid))],
        )
        .await?;
    }
    cx.exec("DELETE FROM usergroups_roles WHERE usergroup_id = $1", vec![Bind::I(Some(id))]).await?;
    for r in &g.roles {
        let rid = r.id.ok_or("object references an unsaved transient instance: Role")?;
        cx.exec(
            "INSERT INTO usergroups_roles (usergroup_id, role_id) VALUES ($1, $2)",
            vec![Bind::I(Some(id)), Bind::I(Some(rid))],
        )
        .await?;
    }
    Ok(())
}

fn check_not_loaded(cx: &Ctx, kind: &'static str, id: Option<i32>) -> DbRes<()> {
    if let Some(i) = id {
        if cx.loaded.contains(&(kind, i)) {
            return Err(format!("A different object with the same identifier value was already associated with the session: {kind} {i}"));
        }
    }
    Ok(())
}

pub async fn save_extent(cx: &mut Ctx, x: &mut Extent, cascade: bool) -> DbRes<Option<i32>> {
    if !cascade && x.id.is_some() {
        return Ok(x.id);
    }
    let lx = x.lower_left.map(|p| p.x);
    let ly = x.lower_left.map(|p| p.y);
    let ux = x.upper_right.map(|p| p.x);
    let uy = x.upper_right.map(|p| p.y);
    match x.id {
        None => {
            let id = cx.alloc_id().await?;
            x.id = Some(id);
            cx.exec(
                "INSERT INTO extents (id, created, modified, lowerleft_x, lowerleft_y, upperright_x, upperright_y) \
                 VALUES ($1, now(), now(), $2, $3, $4, $5)",
                vec![Bind::I(Some(id)), Bind::F(lx), Bind::F(ly), Bind::F(ux), Bind::F(uy)],
            )
            .await?;
        }
        Some(id) => {
            check_not_loaded(cx, "extent", Some(id))?;
            cx.update_one(
                "UPDATE extents SET modified = now(), lowerleft_x = $2, lowerleft_y = $3, upperright_x = $4, upperright_y = $5 WHERE id = $1",
                vec![Bind::I(Some(id)), Bind::F(lx), Bind::F(ly), Bind::F(ux), Bind::F(uy)],
            )
            .await?;
        }
    }
    Ok(x.id)
}

/// Saves a tile grid. `cascade` is false for a grid that the request did not
/// change (it is only referenced).
pub async fn save_tile_grid(cx: &mut Ctx, t: &mut TileGrid, cascade: bool) -> DbRes<Option<i32>> {
    if !cascade && t.id.is_some() {
        return Ok(t.id);
    }
    let ext_id = match &mut t.extent {
        None => None,
        Some(x) => save_extent(cx, x, true).await?,
    };
    let ox = t.origin.map(|p| p.x);
    let oy = t.origin.map(|p| p.y);
    match t.id {
        None => {
            let id = cx.alloc_id().await?;
            t.id = Some(id);
            cx.exec(
                "INSERT INTO tilegrids (id, created, modified, tilegridorigin_x, tilegridorigin_y, tilesize, type, tilegridextent_id) \
                 VALUES ($1, now(), now(), $2, $3, $4, $5, $6)",
                vec![Bind::I(Some(id)), Bind::F(ox), Bind::F(oy), bi(t.tile_size), bs(&t.type_), Bind::I(ext_id)],
            )
            .await?;
        }
        Some(id) => {
            check_not_loaded(cx, "tilegrid", Some(id))?;
            cx.update_one(
                "UPDATE tilegrids SET modified = now(), tilegridorigin_x = $2, tilegridorigin_y = $3, tilesize = $4, \
                 type = $5, tilegridextent_id = $6 WHERE id = $1",
                vec![Bind::I(Some(id)), Bind::F(ox), Bind::F(oy), bi(t.tile_size), bs(&t.type_), Bind::I(ext_id)],
            )
            .await?;
        }
    }
    let id = t.id.unwrap_or_default();
    cx.exec("DELETE FROM tilegrid_resolution WHERE tilegrid_id = $1", vec![Bind::I(Some(id))]).await?;
    if let Some(res) = &t.resolutions {
        for (idx, r) in res.iter().enumerate() {
            cx.exec(
                "INSERT INTO tilegrid_resolution (tilegrid_id, resolution, idx) VALUES ($1, $2, $3)",
                vec![Bind::I(Some(id)), Bind::F(Some(*r)), Bind::I(Some(idx as i32))],
            )
            .await?;
        }
    }
    if t.wmts {
        let exists = sqlx::query_scalar::<_, i64>("SELECT count(*) FROM wmtstilegrids WHERE id = $1")
            .bind(id)
            .fetch_one(&mut *cx.tx)
            .await
            .map_err(e)?;
        if exists == 0 {
            cx.exec("INSERT INTO wmtstilegrids (id) VALUES ($1)", vec![Bind::I(Some(id))]).await?;
        }
        cx.exec("DELETE FROM wmtstilegrids_matrixids WHERE wmtstilegrids_id = $1", vec![Bind::I(Some(id))]).await?;
        if let Some(ids) = &t.matrix_ids {
            for m in ids {
                cx.exec(
                    "INSERT INTO wmtstilegrids_matrixids (wmtstilegrids_id, matrixids) VALUES ($1, $2)",
                    vec![Bind::I(Some(id)), Bind::S(Some(m.clone()))],
                )
                .await?;
            }
        }
    }
    Ok(t.id)
}

pub async fn save_appearance(cx: &mut Ctx, a: &mut Appearance, cascade: bool) -> DbRes<Option<i32>> {
    if !cascade && a.id.is_some() {
        return Ok(a.id);
    }
    let max = a.max_resolution;
    let min = a.min_resolution;
    let opacity = a.opacity;
    match a.id {
        None => {
            let id = cx.alloc_id().await?;
            a.id = Some(id);
            cx.exec(
                "INSERT INTO layerappearances (id, created, modified, attribution, clickable, hovertemplate, hoverable, \
                 maxresolution, minresolution, name, opacity, visible) VALUES ($1, now(), now(), $2, $3, $4, $5, $6, $7, $8, $9, $10)",
                vec![
                    Bind::I(Some(id)), bs(&a.attribution), Bind::B(a.clickable), bs(&a.hover_template), Bind::B(a.hoverable),
                    Bind::F(max), Bind::F(min), bs(&a.name), Bind::F(opacity), Bind::B(a.visible),
                ],
            )
            .await?;
        }
        Some(id) => {
            check_not_loaded(cx, "appearance", Some(id))?;
            cx.update_one(
                "UPDATE layerappearances SET modified = now(), attribution = $2, clickable = $3, hovertemplate = $4, \
                 hoverable = $5, maxresolution = $6, minresolution = $7, name = $8, opacity = $9, visible = $10 WHERE id = $1",
                vec![
                    Bind::I(Some(id)), bs(&a.attribution), Bind::B(a.clickable), bs(&a.hover_template), Bind::B(a.hoverable),
                    Bind::F(max), Bind::F(min), bs(&a.name), Bind::F(opacity), Bind::B(a.visible),
                ],
            )
            .await?;
        }
    }
    let id = a.id.unwrap_or_default();
    cx.exec("DELETE FROM layerappearances_properties WHERE appearance_id = $1", vec![Bind::I(Some(id))]).await?;
    if let Some(props) = &a.properties {
        for (k, v) in props {
            let text = property_value_text(v)?;
            cx.exec(
                "INSERT INTO layerappearances_properties (appearance_id, property, value) VALUES ($1, $2, $3)",
                vec![Bind::I(Some(id)), Bind::S(Some(k.clone())), Bind::S(Some(text))],
            )
            .await?;
        }
    }
    Ok(a.id)
}

/// Saves a data source (the base row and the subclass rows). `grid_cascade`
/// tells whether the tile grid (or WMTS grid) was given by the request.
pub async fn save_source(cx: &mut Ctx, s: &mut DataSource, grid_cascade: bool) -> DbRes<()> {
    let id = s.id.ok_or("cannot create a LayerDataSource")?;
    cx.update_one(
        "UPDATE layerdatasources SET modified = now(), format = $2, name = $3, type = $4, url = $5 WHERE id = $1",
        vec![Bind::I(Some(id)), bs(&s.format), bs(&s.name), bs(&s.type_), bs(&s.url)],
    )
    .await?;
    match &mut s.kind {
        SourceKind::ImageWms(i) => update_image(cx, id, i).await?,
        SourceKind::TileWms(t) => {
            let grid = match &mut t.tile_grid {
                None => None,
                Some(g) => save_tile_grid(cx, g, grid_cascade).await?,
            };
            update_image(cx, id, &t.image).await?;
            cx.update_one(
                "UPDATE tilewmslayerdatasources SET request_with_tiled = $2, tilegrid_id = $3 WHERE id = $1",
                vec![Bind::I(Some(id)), Bind::B(t.request_with_tiled), Bind::I(grid)],
            )
            .await?;
        }
        SourceKind::Wfs(w) => {
            cx.update_one(
                "UPDATE wfslayerdatasources SET typename = $2, typenames = $3, version = $4 WHERE id = $1",
                vec![Bind::I(Some(id)), bs(&w.type_name), bs(&w.type_names), bs(&w.version)],
            )
            .await?;
        }
        SourceKind::Wmts(w) => {
            let grid = match &mut w.tile_grid {
                None => None,
                Some(g) => save_tile_grid(cx, g, grid_cascade).await?,
            };
            cx.update_one(
                "UPDATE wmtslayerdatasources SET capabilitiesurl = $2, matrixset = $3, projection = $4, \
                 requestencoding = $5, wmtslayer = $6, wmtsstyle = $7, tilegrid_id = $8 WHERE id = $1",
                vec![
                    Bind::I(Some(id)), bs(&w.capabilities_url), bs(&w.matrix_set), bs(&w.projection),
                    bs(&w.request_encoding), bs(&w.wmts_layer), bs(&w.wmts_style), Bind::I(grid),
                ],
            )
            .await?;
            cx.exec("DELETE FROM wmtslayerdatasources_urls WHERE wmtslayerdatasources_id = $1", vec![Bind::I(Some(id))]).await?;
            if let Some(urls) = &w.urls {
                for u in urls {
                    cx.exec(
                        "INSERT INTO wmtslayerdatasources_urls (wmtslayerdatasources_id, urls) VALUES ($1, $2)",
                        vec![Bind::I(Some(id)), Bind::S(Some(u.clone()))],
                    )
                    .await?;
                }
            }
        }
        SourceKind::Xyz(x) => {
            // OneToOne without cascade: the extent must be a saved entity.
            let ext = match &x.extent {
                None => None,
                Some(ex) => Some(ex.id.ok_or("object references an unsaved transient instance: Extent")?),
            };
            cx.update_one(
                "UPDATE xyzlayerdatasources SET center_x = $2, center_y = $3, tilesize = $4, extent_id = $5 WHERE id = $1",
                vec![
                    Bind::I(Some(id)),
                    Bind::F(x.center.map(|p| p.x)),
                    Bind::F(x.center.map(|p| p.y)),
                    bi(x.tile_size),
                    Bind::I(ext),
                ],
            )
            .await?;
            cx.exec("DELETE FROM xyzlayerdatasrc_resolution WHERE xyzlayerdatasrc_id = $1", vec![Bind::I(Some(id))]).await?;
            for (idx, r) in x.resolutions.iter().enumerate() {
                cx.exec(
                    "INSERT INTO xyzlayerdatasrc_resolution (xyzlayerdatasrc_id, resolution, idx) VALUES ($1, $2, $3)",
                    vec![Bind::I(Some(id)), Bind::Bytes(java_double_bytes(*r)), Bind::I(Some(idx as i32))],
                )
                .await?;
            }
        }
    }
    Ok(())
}

async fn update_image(cx: &mut Ctx, id: i32, i: &ImageWms) -> DbRes<()> {
    cx.update_one(
        "UPDATE imagewmslayerdatasources SET customrequestpath = $2, height = $3, layernames = $4, layerstyles = $5, \
         requestablebypath = $6, version = $7, width = $8 WHERE id = $1",
        vec![
            Bind::I(Some(id)), bs(&i.custom_request_path), Bind::I(Some(i.height)), bs(&i.layer_names),
            bs(&i.layer_styles), Bind::B(i.requestable_by_path), bs(&i.version), Bind::I(Some(i.width)),
        ],
    )
    .await
}

/// Saves a layer. The appearance is cascaded (SAVE_UPDATE) when the request
/// gave it (or the layer is new); the source must be a loaded, saved one.
pub async fn save_layer(cx: &mut Ctx, l: &mut Layer, appearance_cascade: bool) -> DbRes<()> {
    let app_id = match &mut l.appearance {
        None => None,
        Some(a) => save_appearance(cx, a, appearance_cascade).await?,
    };
    let src_id = match &l.source {
        None => None,
        Some(s) => Some(s.id.ok_or("object references an unsaved transient instance: LayerDataSource")?),
    };
    match l.id {
        None => {
            let id = cx.alloc_id().await?;
            l.id = Some(id);
            cx.exec(
                "INSERT INTO layers (id, created, modified, description, name, appearance_id, source_id) \
                 VALUES ($1, now(), now(), $2, $3, $4, $5)",
                vec![Bind::I(Some(id)), bs(&l.description), bs(&l.name), Bind::I(app_id), Bind::I(src_id)],
            )
            .await?;
        }
        Some(id) => {
            cx.update_one(
                "UPDATE layers SET modified = now(), description = $2, name = $3, appearance_id = $4, source_id = $5 WHERE id = $1",
                vec![Bind::I(Some(id)), bs(&l.description), bs(&l.name), Bind::I(app_id), Bind::I(src_id)],
            )
            .await?;
        }
    }
    Ok(())
}

// ---------------------------------------------------------------------------
// Deleting (own collections first, then the rows, as Hibernate does)
// ---------------------------------------------------------------------------

pub async fn delete_permissions(cx: &mut Ctx, id: i32) -> DbRes<()> {
    cx.exec("DELETE FROM userpermissions WHERE entity_id = $1", vec![Bind::I(Some(id))]).await?;
    cx.exec("DELETE FROM grouppermissions WHERE entity_id = $1", vec![Bind::I(Some(id))]).await?;
    Ok(())
}

pub async fn delete_user(cx: &mut Ctx, id: i32) -> DbRes<()> {
    cx.exec("DELETE FROM users_roles WHERE user_id = $1", vec![Bind::I(Some(id))]).await?;
    cx.exec("DELETE FROM user_usergroup WHERE user_id = $1", vec![Bind::I(Some(id))]).await?;
    delete_permissions(cx, id).await?;
    cx.update_one("DELETE FROM users WHERE id = $1", vec![Bind::I(Some(id))]).await?;
    cx.update_one("DELETE FROM persons WHERE id = $1", vec![Bind::I(Some(id))]).await?;
    Ok(())
}

pub async fn delete_group(cx: &mut Ctx, id: i32) -> DbRes<()> {
    cx.exec("DELETE FROM usergroups_roles WHERE usergroup_id = $1", vec![Bind::I(Some(id))]).await?;
    cx.exec("DELETE FROM user_usergroup WHERE usergroup_id = $1", vec![Bind::I(Some(id))]).await?;
    delete_permissions(cx, id).await?;
    cx.update_one("DELETE FROM usergroups WHERE id = $1", vec![Bind::I(Some(id))]).await
}

pub async fn delete_role(cx: &mut Ctx, id: i32) -> DbRes<()> {
    delete_permissions(cx, id).await?;
    cx.update_one("DELETE FROM roles WHERE id = $1", vec![Bind::I(Some(id))]).await
}

pub async fn delete_appearance(cx: &mut Ctx, id: i32) -> DbRes<()> {
    cx.exec("DELETE FROM layerappearances_properties WHERE appearance_id = $1", vec![Bind::I(Some(id))]).await?;
    delete_permissions(cx, id).await?;
    cx.update_one("DELETE FROM layerappearances WHERE id = $1", vec![Bind::I(Some(id))]).await
}

/// Removes a layer from the maps that list it (`LayerService.delete`), keeping
/// the list order (the `idx` column is renumbered).
pub async fn remove_layer_from_maps(cx: &mut Ctx, layer_id: i32) -> DbRes<()> {
    let maps: Vec<i32> = sqlx::query_scalar("SELECT DISTINCT map_id FROM maps_layers WHERE layer_id = $1")
        .bind(layer_id)
        .fetch_all(&mut *cx.tx)
        .await
        .map_err(e)?;
    for m in maps {
        let rows: Vec<(i32, i32)> = sqlx::query_as("SELECT layer_id, idx FROM maps_layers WHERE map_id = $1 ORDER BY idx")
            .bind(m)
            .fetch_all(&mut *cx.tx)
            .await
            .map_err(e)?;
        let kept: Vec<i32> = rows.into_iter().map(|r| r.0).filter(|l| *l != layer_id).collect();
        cx.exec("DELETE FROM maps_layers WHERE map_id = $1", vec![Bind::I(Some(m))]).await?;
        for (idx, l) in kept.iter().enumerate() {
            cx.exec(
                "INSERT INTO maps_layers (map_id, layer_id, idx) VALUES ($1, $2, $3)",
                vec![Bind::I(Some(m)), Bind::I(Some(*l)), Bind::I(Some(idx as i32))],
            )
            .await?;
        }
    }
    Ok(())
}

pub async fn delete_layer(cx: &mut Ctx, id: i32) -> DbRes<()> {
    remove_layer_from_maps(cx, id).await?;
    delete_permissions(cx, id).await?;
    cx.update_one("DELETE FROM layers WHERE id = $1", vec![Bind::I(Some(id))]).await
}

/// Deletes a data source with its subclass rows. The WMTS tile grid cascades
/// (CascadeType.ALL); other referenced rows stay.
pub async fn delete_source(cx: &mut Ctx, s: &DataSource) -> DbRes<()> {
    let id = s.id.ok_or("no id")?;
    match &s.kind {
        SourceKind::ImageWms(_) => {
            cx.update_one("DELETE FROM imagewmslayerdatasources WHERE id = $1", vec![Bind::I(Some(id))]).await?;
        }
        SourceKind::TileWms(_) => {
            cx.update_one("DELETE FROM tilewmslayerdatasources WHERE id = $1", vec![Bind::I(Some(id))]).await?;
            cx.update_one("DELETE FROM imagewmslayerdatasources WHERE id = $1", vec![Bind::I(Some(id))]).await?;
        }
        SourceKind::Wfs(_) => {
            cx.update_one("DELETE FROM wfslayerdatasources WHERE id = $1", vec![Bind::I(Some(id))]).await?;
        }
        SourceKind::Wmts(w) => {
            cx.exec("DELETE FROM wmtslayerdatasources_urls WHERE wmtslayerdatasources_id = $1", vec![Bind::I(Some(id))]).await?;
            cx.update_one("DELETE FROM wmtslayerdatasources WHERE id = $1", vec![Bind::I(Some(id))]).await?;
            if let Some(g) = &w.tile_grid {
                if let Some(gid) = g.id {
                    cx.exec("DELETE FROM wmtstilegrids_matrixids WHERE wmtstilegrids_id = $1", vec![Bind::I(Some(gid))]).await?;
                    cx.exec("DELETE FROM tilegrid_resolution WHERE tilegrid_id = $1", vec![Bind::I(Some(gid))]).await?;
                    cx.update_one("DELETE FROM wmtstilegrids WHERE id = $1", vec![Bind::I(Some(gid))]).await?;
                    cx.update_one("DELETE FROM tilegrids WHERE id = $1", vec![Bind::I(Some(gid))]).await?;
                }
            }
        }
        SourceKind::Xyz(_) => {
            cx.exec("DELETE FROM xyzlayerdatasrc_resolution WHERE xyzlayerdatasrc_id = $1", vec![Bind::I(Some(id))]).await?;
            cx.update_one("DELETE FROM xyzlayerdatasources WHERE id = $1", vec![Bind::I(Some(id))]).await?;
        }
    }
    if let SourceKind::TileWms(_) = &s.kind {
        // the subclass row of the tile source is removed above
    }
    delete_permissions(cx, id).await?;
    cx.update_one("DELETE FROM layerdatasources WHERE id = $1", vec![Bind::I(Some(id))]).await
}

tool_use_result.content:
//! Database access: loading entities with their related rows, and saving them
//! as Hibernate would for the mapping of shogun-core on the schema of
//! `schema.sql` (JOINED inheritance for persons/users, layers and data
//! sources; ids from the `hibernate_sequences` table).

use crate::model::*;
use sqlx::postgres::PgRow;
use sqlx::pool::PoolConnection;
use sqlx::{PgConnection, Postgres, Row, Transaction};
use std::collections::{HashMap, HashSet};

pub type DbRes<T> = Result<T, String>;

fn e<E: std::fmt::Display>(err: E) -> String {
    err.to_string()
}

/// One request's database work: a transaction (committed on success) and a
/// separate connection for id allocation (Hibernate's table generator works
/// in its own transaction, so ids are consumed even if the request fails).
pub struct Ctx {
    pub tx: Transaction<'static, Postgres>,
    pub ids: PoolConnection<Postgres>,
    /// Entities that the Hibernate session of the request has loaded already.
    /// Saving a detached object with one of these ids through a cascade is a
    /// `NonUniqueObjectException` in the original.
    pub loaded: HashSet<(&'static str, i32)>,
}

impl Ctx {
    pub fn c(&mut self) -> &mut PgConnection {
        &mut self.tx
    }

    pub async fn alloc_id(&mut self) -> DbRes<i32> {
        // Hibernate's TableGenerator (default segment, allocation size 1):
        // new id = next_val + 1, and next_val becomes the new id.
        let v: i64 = sqlx::query_scalar(
            "UPDATE hibernate_sequences SET next_val = next_val + 1 \
             WHERE sequence_name = 'default' RETURNING next_val",
        )
        .fetch_one(&mut *self.ids)
        .await
        .map_err(e)?;
        i32::try_from(v).map_err(|_| "id out of range".to_string())
    }

    pub async fn exec(&mut self, sql: &str, binds: Vec<Bind>) -> DbRes<u64> {
        let mut q = sqlx::query(sql);
        for b in binds {
            q = b.bind(q);
        }
        let r = q.execute(&mut *self.tx).await.map_err(e)?;
        Ok(r.rows_affected())
    }

    /// Updates a row that must exist (Hibernate's StaleStateException otherwise).
    pub async fn update_one(&mut self, sql: &str, binds: Vec<Bind>) -> DbRes<()> {
        let n = self.exec(sql, binds).await?;
        if n != 1 {
            return Err("Row was updated or deleted by another transaction".into());
        }
        Ok(())
    }
}

/// Values bound to the statements.
#[derive(Clone)]
pub enum Bind {
    I(Option<i32>),
    F(Option<f64>),
    B(Option<bool>),
    S(Option<String>),
    D(Option<chrono::NaiveDate>),
    Bytes(Vec<u8>),
}

impl Bind {
    fn bind<'q>(self, q: sqlx::query::Query<'q, Postgres, sqlx::postgres::PgArguments>) -> sqlx::query::Query<'q, Postgres, sqlx::postgres::PgArguments> {
        match self {
            Bind::I(v) => q.bind(v),
            Bind::F(v) => q.bind(v),
            Bind::B(v) => q.bind(v),
            Bind::S(v) => q.bind(v),
            Bind::D(v) => q.bind(v),
            Bind::Bytes(v) => q.bind(v),
        }
    }
}

pub fn bi(v: Option<i32>) -> Bind {
    Bind::I(v)
}
pub fn bs(v: &Option<String>) -> Bind {
    Bind::S(v.clone())
}

// ---------------------------------------------------------------------------
// Loading
// ---------------------------------------------------------------------------

fn ids_filter(ids: &Option<Vec<i32>>) -> Option<Vec<i32>> {
    ids.clone()
}

async fn fetch(cx: &mut Ctx, sql: &str, ids: &Option<Vec<i32>>) -> DbRes<Vec<PgRow>> {
    let rows = match ids_filter(ids) {
        None => sqlx::query(sql).fetch_all(&mut *cx.tx).await,
        Some(v) => sqlx::query(&format!("{sql} WHERE id = ANY($1)")).bind(v).fetch_all(&mut *cx.tx).await,
    };
    rows.map_err(e)
}

fn point_from(x: Option<f64>, y: Option<f64>) -> Option<Point> {
    if x.is_none() && y.is_none() {
        None
    } else {
        Some(Point { x: x.unwrap_or(0.0), y: y.unwrap_or(0.0) })
    }
}

pub async fn load_roles(cx: &mut Ctx, ids: Option<Vec<i32>>) -> DbRes<HashMap<i32, Role>> {
    let rows = fetch(cx, "SELECT id, name, description FROM roles", &ids).await?;
    let mut out = HashMap::new();
    for r in rows {
        let id: i32 = r.get("id");
        out.insert(
            id,
            Role {
                id: Some(id),
                name: r.get("name"),
                description: r.get("description"),
            },
        );
    }
    Ok(out)
}

/// Users with their roles and the ids of their groups.
pub async fn load_users(cx: &mut Ctx, ids: Option<Vec<i32>>) -> DbRes<HashMap<i32, User>> {
    let mut users: HashMap<i32, User> = HashMap::new();
    let rows = match &ids {
        None => sqlx::query(
            "SELECT p.id, p.firstname, p.lastname, p.email, p.birthday, p.language, \
             u.accountname, u.password, u.active FROM users u JOIN persons p ON p.id = u.id ORDER BY u.id",
        )
        .fetch_all(&mut *cx.tx)
        .await,
        Some(v) => sqlx::query(
            "SELECT p.id, p.firstname, p.lastname, p.email, p.birthday, p.language, \
             u.accountname, u.password, u.active FROM users u JOIN persons p ON p.id = u.id WHERE u.id = ANY($1)",
        )
        .bind(v.clone())
        .fetch_all(&mut *cx.tx)
        .await,
    }
    .map_err(e)?;
    for r in rows {
        let id: i32 = r.get("id");
        users.insert(
            id,
            User {
                id: Some(id),
                first_name: r.get("firstname"),
                last_name: r.get("lastname"),
                email: r.get("email"),
                birthday: r.get("birthday"),
                language: r.get("language"),
                account_name: r.get("accountname"),
                password: r.get("password"),
                active: r.get::<Option<bool>, _>("active").unwrap_or(false),
                roles: Vec::new(),
                user_groups: Vec::new(),
            },
        );
    }
    if users.is_empty() {
        return Ok(users);
    }
    let user_ids: Vec<i32> = users.keys().copied().collect();
    let roles = sqlx::query("SELECT user_id, role_id FROM users_roles WHERE user_id = ANY($1) ORDER BY role_id")
        .bind(user_ids.clone())
        .fetch_all(&mut *cx.tx)
        .await
        .map_err(e)?;
    let role_ids: Vec<i32> = roles.iter().map(|r| r.get::<i32, _>("role_id")).collect();
    let role_map = if role_ids.is_empty() { HashMap::new() } else { load_roles(cx, Some(role_ids)).await? };
    for r in roles {
        let uid: i32 = r.get("user_id");
        let rid: i32 = r.get("role_id");
        if let (Some(u), Some(role)) = (users.get_mut(&uid), role_map.get(&rid)) {
            u.roles.push(role.clone());
        }
    }
    let groups = sqlx::query("SELECT user_id, usergroup_id FROM user_usergroup WHERE user_id = ANY($1) ORDER BY usergroup_id")
        .bind(user_ids)
        .fetch_all(&mut *cx.tx)
        .await
        .map_err(e)?;
    for g in groups {
        let uid: i32 = g.get("user_id");
        if let Some(u) = users.get_mut(&uid) {
            u.user_groups.push(g.get("usergroup_id"));
        }
    }
    Ok(users)
}

pub async fn load_user(cx: &mut Ctx, id: i32) -> DbRes<Option<User>> {
    Ok(load_users(cx, Some(vec![id])).await?.remove(&id))
}

/// Groups with owner, members and roles (members/owner loaded without their groups).
pub async fn load_groups(cx: &mut Ctx, ids: Option<Vec<i32>>) -> DbRes<Vec<Group>> {
    let rows = fetch(cx, "SELECT id, name, owner_id FROM usergroups", &ids).await?;
    let mut groups: Vec<(i32, Group, Option<i32>)> = Vec::new();
    for r in rows {
        let id: i32 = r.get("id");
        let owner: Option<i32> = r.get("owner_id");
        groups.push((
            id,
            Group { id: Some(id), name: r.get("name"), owner: None, members: Vec::new(), roles: Vec::new() },
            owner,
        ));
    }
    if groups.is_empty() {
        return Ok(vec![]);
    }
    let gids: Vec<i32> = groups.iter().map(|g| g.0).collect();
    let owner_ids: Vec<i32> = groups.iter().filter_map(|g| g.2).collect();
    let owners = if owner_ids.is_empty() { HashMap::new() } else { load_users(cx, Some(owner_ids)).await? };
    let members_rows = sqlx::query("SELECT usergroup_id, user_id FROM user_usergroup WHERE usergroup_id = ANY($1) ORDER BY user_id")
        .bind(gids.clone())
        .fetch_all(&mut *cx.tx)
        .await
        .map_err(e)?;
    let member_ids: Vec<i32> = members_rows.iter().map(|r| r.get::<i32, _>("user_id")).collect();
    let members = if member_ids.is_empty() { HashMap::new() } else { load_users(cx, Some(member_ids)).await? };
    let role_rows = sqlx::query("SELECT usergroup_id, role_id FROM usergroups_roles WHERE usergroup_id = ANY($1) ORDER BY role_id")
        .bind(gids)
        .fetch_all(&mut *cx.tx)
        .await
        .map_err(e)?;
    let role_ids: Vec<i32> = role_rows.iter().map(|r| r.get::<i32, _>("role_id")).collect();
    let roles = if role_ids.is_empty() { HashMap::new() } else { load_roles(cx, Some(role_ids)).await? };

    let mut out = Vec::new();
    for (id, mut g, owner) in groups {
        g.owner = owner.and_then(|o| owners.get(&o).cloned()).map(Box::new);
        for r in members_rows.iter().filter(|r| r.get::<i32, _>("usergroup_id") == id) {
            if let Some(u) = members.get(&r.get::<i32, _>("user_id")) {
                g.members.push(u.clone());
            }
        }
        for r in role_rows.iter().filter(|r| r.get::<i32, _>("usergroup_id") == id) {
            if let Some(role) = roles.get(&r.get::<i32, _>("role_id")) {
                g.roles.push(role.clone());
            }
        }
        out.push(g);
    }
    Ok(out)
}

pub async fn load_group(cx: &mut Ctx, id: i32) -> DbRes<Option<Group>> {
    Ok(load_groups(cx, Some(vec![id])).await?.pop())
}

fn load_point_pair(r: &PgRow, xcol: &str, ycol: &str) -> Option<Point> {
    point_from(r.get::<Option<f64>, _>(xcol), r.get::<Option<f64>, _>(ycol))
}

pub async fn load_extents(cx: &mut Ctx, ids: Option<Vec<i32>>) -> DbRes<HashMap<i32, Extent>> {
    let rows = fetch(
        cx,
        "SELECT id, lowerleft_x, lowerleft_y, upperright_x, upperright_y FROM extents",
        &ids,
    )
    .await?;
    let mut out = HashMap::new();
    for r in rows {
        let id: i32 = r.get("id");
        out.insert(
            id,
            Extent {
                id: Some(id),
                lower_left: point_from(r.get("lowerleft_x"), r.get("lowerleft_y")),
                upper_right: point_from(r.get("upperright_x"), r.get("upperright_y")),
            },
        );
    }
    Ok(out)
}

pub async fn load_tile_grids(cx: &mut Ctx, ids: Option<Vec<i32>>) -> DbRes<HashMap<i32, TileGrid>> {
    let rows = fetch(
        cx,
        "SELECT id, tilegridorigin_x, tilegridorigin_y, tilesize, type, tilegridextent_id FROM tilegrids",
        &ids,
    )
    .await?;
    let mut out: HashMap<i32, TileGrid> = HashMap::new();
    let mut extent_ids = Vec::new();
    for r in &rows {
        let id: i32 = r.get("id");
        let ext: Option<i32> = r.get("tilegridextent_id");
        if let Some(x) = ext {
            extent_ids.push(x);
        }
        out.insert(
            id,
            TileGrid {
                id: Some(id),
                type_: r.get("type"),
                origin: load_point_pair(r, "tilegridorigin_x", "tilegridorigin_y"),
                extent: None,
                tile_size: r.get("tilesize"),
                resolutions: Some(Vec::new()),
                wmts: false,
                matrix_ids: None,
            },
        );
    }
    if out.is_empty() {
        return Ok(out);
    }
    let keys: Vec<i32> = out.keys().copied().collect();
    let extents = if extent_ids.is_empty() { HashMap::new() } else { load_extents(cx, Some(extent_ids)).await? };
    for r in &rows {
        let id: i32 = r.get("id");
        let ext: Option<i32> = r.get("tilegridextent_id");
        if let (Some(t), Some(x)) = (out.get_mut(&id), ext) {
            t.extent = extents.get(&x).cloned();
        }
    }
    let wmts = sqlx::query("SELECT id FROM wmtstilegrids WHERE id = ANY($1)")
        .bind(keys.clone())
        .fetch_all(&mut *cx.tx)
        .await
        .map_err(e)?;
    for r in wmts {
        let id: i32 = r.get("id");
        if let Some(t) = out.get_mut(&id) {
            t.wmts = true;
            t.matrix_ids = Some(Vec::new());
        }
    }
    let mids = sqlx::query("SELECT wmtstilegrids_id, matrixids FROM wmtstilegrids_matrixids WHERE wmtstilegrids_id = ANY($1)")
        .bind(keys.clone())
        .fetch_all(&mut *cx.tx)
        .await
        .map_err(e)?;
    for r in mids {
        let id: i32 = r.get("wmtstilegrids_id");
        if let Some(t) = out.get_mut(&id) {
            t.matrix_ids.get_or_insert_with(Vec::new).push(r.get::<Option<String>, _>("matrixids").unwrap_or_default());
        }
    }
    let res = sqlx::query("SELECT tilegrid_id, resolution FROM tilegrid_resolution WHERE tilegrid_id = ANY($1) ORDER BY idx")
        .bind(keys)
        .fetch_all(&mut *cx.tx)
        .await
        .map_err(e)?;
    for r in res {
        let id: i32 = r.get("tilegrid_id");
        if let Some(t) = out.get_mut(&id) {
            t.resolutions.get_or_insert_with(Vec::new).push(r.get::<Option<f64>, _>("resolution").unwrap_or(0.0));
        }
    }
    Ok(out)
}

pub async fn load_appearances(cx: &mut Ctx, ids: Option<Vec<i32>>) -> DbRes<HashMap<i32, Appearance>> {
    let rows = fetch(
        cx,
        "SELECT id, attribution, clickable, hovertemplate, hoverable, maxresolution, minresolution, name, opacity, visible \
         FROM layerappearances",
        &ids,
    )
    .await?;
    let mut out = HashMap::new();
    for r in rows {
        let id: i32 = r.get("id");
        out.insert(
            id,
            Appearance {
                id: Some(id),
                attribution: r.get("attribution"),
                hoverable: r.get("hoverable"),
                clickable: r.get("clickable"),
                hover_template: r.get("hovertemplate"),
                properties: Some(Vec::new()),
                name: r.get("name"),
                max_resolution: r.get("maxresolution"),
                min_resolution: r.get("minresolution"),
                opacity: r.get("opacity"),
                visible: r.get("visible"),
            },
        );
    }
    if out.is_empty() {
        return Ok(out);
    }
    let keys: Vec<i32> = out.keys().copied().collect();
    let props = sqlx::query("SELECT appearance_id, property, value FROM layerappearances_properties WHERE appearance_id = ANY($1) ORDER BY property")
        .bind(keys)
        .fetch_all(&mut *cx.tx)
