/// Role names granted to a user: its roles and the roles of its groups.
pub async fn authorities(cx: &mut Ctx, user_id: i32) -> DbRes<HashSet<String>> {
    let rows = sqlx::query(
        "SELECT r.name FROM users_roles ur JOIN roles r ON r.id = ur.role_id WHERE ur.user_id = $1 \
         UNION SELECT r.name FROM user_usergroup ug JOIN usergroups_roles gr ON gr.usergroup_id = ug.usergroup_id \
         JOIN roles r ON r.id = gr.role_id WHERE ug.user_id = $1",
    )
    .bind(user_id)
    .fetch_all(&mut *cx.tx)
    .await
    .map_err(e)?;
