// Deleting (own collections first, then the rows, as Hibernate does)
// ---------------------------------------------------------------------------

pub async fn delete_permissions(cx: &mut Ctx, id: i32) -> DbRes<()> {
    cx.exec("DELETE FROM userpermissions WHERE entity_id = $1", vec![Bind::I(Some(id))]).await?;
    cx.exec("DELETE FROM grouppermissions WHERE entity_id = $1", vec![Bind::I(Some(id))]).await?;
    Ok(())
}

pub async fn delete_user(cx: &mut Ctx, id: i32) -> DbRes<()> {
    cx.exec("DELETE FROM users_roles WHERE user_id = $1", vec![Bind::I(Some(id))]).await?;
    cx.exec("DELETE FROM user_usergroup WHERE user_id = $1", vec![Bind::I(Some(id))]).await?;
    delete_permissions(cx, id).await?;
    cx.update_one("DELETE FROM users WHERE id = $1", vec![Bind::I(Some(id))]).await?;
    cx.update_one("DELETE FROM persons WHERE id = $1", vec![Bind::I(Some(id))]).await?;
    Ok(())
}

pub async fn delete_group(cx: &mut Ctx, id: i32) -> DbRes<()> {
    cx.exec("DELETE FROM usergroups_roles WHERE usergroup_id = $1", vec![Bind::I(Some(id))]).await?;
    cx.exec("DELETE FROM user_usergroup WHERE usergroup_id = $1", vec![Bind::I(Some(id))]).await?;
    delete_permissions(cx, id).await?;
    cx.update_one("DELETE FROM usergroups WHERE id = $1", vec![Bind::I(Some(id))]).await
}

pub async fn delete_role(cx: &mut Ctx, id: i32) -> DbRes<()> {
    delete_permissions(cx, id).await?;
    cx.update_one("DELETE FROM roles WHERE id = $1", vec![Bind::I(Some(id))]).await
}

pub async fn delete_appearance(cx: &mut Ctx, id: i32) -> DbRes<()> {
    cx.exec("DELETE FROM layerappearances_properties WHERE appearance_id = $1", vec![Bind::I(Some(id))]).await?;
    delete_permissions(cx, id).await?;
    cx.update_one("DELETE FROM layerappearances WHERE id = $1", vec![Bind::I(Some(id))]).await
}

/// Removes a layer from the maps that list it (`LayerService.delete`), keeping
/// the list order (the `idx` column is renumbered).
pub async fn remove_layer_from_maps(cx: &mut Ctx, layer_id: i32) -> DbRes<()> {
    let maps: Vec<i32> = sqlx::query_scalar("SELECT DISTINCT map_id FROM maps_layers WHERE layer_id = $1")
        .bind(layer_id)
        .fetch_all(&mut *cx.tx)
        .await
        .map_err(e)?;
    for m in maps {
        let rows: Vec<(i32, i32)> = sqlx::query_as("SELECT layer_id, idx FROM maps_layers WHERE map_id = $1 ORDER BY idx")
            .bind(m)
            .fetch_all(&mut *cx.tx)
            .await
            .map_err(e)?;
        let kept: Vec<i32> = rows.into_iter().map(|r| r.0).filter(|l| *l != layer_id).collect();
        cx.exec("DELETE FROM maps_layers WHERE map_id = $1", vec![Bind::I(Some(m))]).await?;
        for (idx, l) in kept.iter().enumerate() {
            cx.exec(
                "INSERT INTO maps_layers (map_id, layer_id, idx) VALUES ($1, $2, $3)",
                vec![Bind::I(Some(m)), Bind::I(Some(*l)), Bind::I(Some(idx as i32))],
            )
            .await?;
        }
    }
    Ok(())
}

pub async fn delete_layer(cx: &mut Ctx, id: i32) -> DbRes<()> {
    remove_layer_from_maps(cx, id).await?;
    delete_permissions(cx, id).await?;
    cx.update_one("DELETE FROM layers WHERE id = $1", vec![Bind::I(Some(id))]).await
}

/// Deletes a data source with its subclass rows. The WMTS tile grid cascades
/// (CascadeType.ALL); other referenced rows stay.
pub async fn delete_source(cx: &mut Ctx, s: &DataSource) -> DbRes<()> {
    let id = s.id.ok_or("no id")?;
    match &s.kind {
        SourceKind::ImageWms(_) => {
            cx.update_one("DELETE FROM imagewmslayerdatasources WHERE id = $1", vec![Bind::I(Some(id))]).await?;
        }
        SourceKind::TileWms(_) => {
            cx.update_one("DELETE FROM tilewmslayerdatasources WHERE id = $1", vec![Bind::I(Some(id))]).await?;
            cx.update_one("DELETE FROM imagewmslayerdatasources WHERE id = $1", vec![Bind::I(Some(id))]).await?;
        }
        SourceKind::Wfs(_) => {
            cx.update_one("DELETE FROM wfslayerdatasources WHERE id = $1", vec![Bind::I(Some(id))]).await?;
        }
        SourceKind::Wmts(w) => {
            cx.exec("DELETE FROM wmtslayerdatasources_urls WHERE wmtslayerdatasources_id = $1", vec![Bind::I(Some(id))]).await?;
            cx.update_one("DELETE FROM wmtslayerdatasources WHERE id = $1", vec![Bind::I(Some(id))]).await?;
            if let Some(g) = &w.tile_grid {
                if let Some(gid) = g.id {
                    cx.exec("DELETE FROM wmtstilegrids_matrixids WHERE wmtstilegrids_id = $1", vec![Bind::I(Some(gid))]).await?;
                    cx.exec("DELETE FROM tilegrid_resolution WHERE tilegrid_id = $1", vec![Bind::I(Some(gid))]).await?;
                    cx.update_one("DELETE FROM wmtstilegrids WHERE id = $1", vec![Bind::I(Some(gid))]).await?;
                    cx.update_one("DELETE FROM tilegrids WHERE id = $1", vec![Bind::I(Some(gid))]).await?;
                }
            }
        }
        SourceKind::Xyz(_) => {
            cx.exec("DELETE FROM xyzlayerdatasrc_resolution WHERE xyzlayerdatasrc_id = $1", vec![Bind::I(Some(id))]).await?;
            cx.update_one("DELETE FROM xyzlayerdatasources WHERE id = $1", vec![Bind::I(Some(id))]).await?;
        }
    }
    if let SourceKind::TileWms(_) = &s.kind {
        // the subclass row of the tile source is removed above
    }
    delete_permissions(cx, id).await?;
    cx.update_one("DELETE FROM layerdatasources WHERE id = $1", vec![Bind::I(Some(id))]).await
}

