//! The six resources and their endpoints (`AbstractRestController` and the
//! `users/{id}/userGroups` and `groups/{id}/users` sub-resources).
//!
//! Status codes follow the original's controllers: a failing POST is 400, a
//! failing PUT or DELETE and a missing or unreadable entity are 404, and the
//! `output:only` of a data source makes Spring answer 500.

use crate::db::{self, Ctx};
use crate::jin;
use crate::jout;
use crate::model::*;
use crate::perms::{self, allowed, EntityPerms, Kind, Perm, Principal};
use serde_json::Value;
use std::collections::HashMap;

pub type Status = u16;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Res {
    Users,
    Groups,
    Roles,
    Layers,
    Sources,
    Appearances,
}

/// Java field types of the restrictable (filterable) properties.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FType {
    Int,
    Str,
    Bool,
    Dbl,
}

impl Res {
    pub fn from_segment(s: &str) -> Option<Res> {
        Some(match s {
            "users" => Res::Users,
            "groups" => Res::Groups,
            "roles" => Res::Roles,
            "layers" => Res::Layers,
            "layerdatasources" => Res::Sources,
            "layerappearances" => Res::Appearances,
            _ => return None,
        })
    }

    pub fn kind(self) -> Kind {
        match self {
            Res::Users => Kind::User,
            Res::Groups => Kind::Group,
            Res::Roles | Res::Sources | Res::Appearances => Kind::AlwaysRead,
            Res::Layers => Kind::Layer,
        }
    }

    /// The non-static primitive, wrapper and String fields of the class
    /// hierarchy (`EntityUtil.getFilterableOrRestrictableFieldNames`).
    pub fn restrictable(self) -> &'static [(&'static str, FType)] {
        use FType::*;
        match self {
            Res::Users => &[
                ("id", Int), ("firstName", Str), ("lastName", Str), ("email", Str),
                ("accountName", Str), ("password", Str), ("active", Bool),
            ],
            Res::Groups => &[("id", Int), ("name", Str)],
            Res::Roles => &[("id", Int), ("name", Str), ("description", Str)],
            Res::Layers => &[("id", Int), ("name", Str), ("description", Str)],
            Res::Sources => &[("id", Int), ("name", Str), ("type", Str), ("url", Str), ("format", Str)],
            Res::Appearances => &[
                ("id", Int), ("attribution", Str), ("hoverable", Bool), ("clickable", Bool),
                ("hoverTemplate", Str), ("name", Str), ("maxResolution", Dbl), ("minResolution", Dbl),
                ("opacity", Dbl), ("visible", Bool),
            ],
        }
    }
}

/// An entity of one of the resources.
#[derive(Clone, Debug)]
pub enum Ent {
    User(User),
    Group(Group),
    Role(Role),
    Layer(Layer),
    Source(DataSource),
    Appearance(Appearance),
}

impl Ent {
    fn id(&self) -> Option<i32> {
        match self {
            Ent::User(e) => e.id,
            Ent::Group(e) => e.id,
            Ent::Role(e) => e.id,
            Ent::Layer(e) => e.id,
            Ent::Source(e) => e.id,
            Ent::Appearance(e) => e.id,
        }
    }

    fn to_json(&self) -> Value {
        match self {
            Ent::User(e) => jout::user(e),
            Ent::Group(e) => jout::group(e),
            Ent::Role(e) => jout::role(e),
            Ent::Layer(e) => jout::layer(e),
            Ent::Source(e) => jout::source(e),
            Ent::Appearance(e) => jout::appearance(e),
        }
    }
}

// ---------------------------------------------------------------------------
// Loading
// ---------------------------------------------------------------------------

async fn load_all(cx: &mut Ctx, res: Res) -> db::DbRes<Vec<Ent>> {
    Ok(match res {
        Res::Users => db::load_users(cx, None).await?.into_values().map(Ent::User).collect(),
        Res::Groups => db::load_groups(cx, None).await?.into_iter().map(Ent::Group).collect(),
        Res::Roles => db::load_roles(cx, None).await?.into_values().map(Ent::Role).collect(),
        Res::Layers => db::load_layers(cx, None).await?.into_iter().map(Ent::Layer).collect(),
        Res::Sources => db::load_sources(cx, None).await?.into_values().map(Ent::Source).collect(),
        Res::Appearances => db::load_appearances(cx, None).await?.into_values().map(Ent::Appearance).collect(),
    })
}

async fn load_one(cx: &mut Ctx, res: Res, id: i32) -> db::DbRes<Option<Ent>> {
    Ok(match res {
        Res::Users => db::load_user(cx, id).await?.map(Ent::User),
        Res::Groups => db::load_group(cx, id).await?.map(Ent::Group),
        Res::Roles => db::load_roles(cx, Some(vec![id])).await?.remove(&id).map(Ent::Role),
        Res::Layers => db::load_layer(cx, id).await?.map(Ent::Layer),
        Res::Sources => db::load_sources(cx, Some(vec![id])).await?.remove(&id).map(Ent::Source),
        Res::Appearances => db::load_appearances(cx, Some(vec![id])).await?.remove(&id).map(Ent::Appearance),
    })
}

/// Registers what the Hibernate session holds after `findById` of an entity:
/// the associations that are fetched eagerly (`@Fetch(FetchMode.JOIN)`).
fn register_loaded(cx: &mut Ctx, ent: &Ent) {
    match ent {
        Ent::Layer(l) => {
            if let Some(a) = l.appearance.as_ref().and_then(|a| a.id) {
                cx.loaded.insert(("appearance", a));
            }
            if let Some(s) = &l.source {
                register_source(cx, s);
            }
        }
        Ent::Source(s) => register_source(cx, s),
        _ => {}
    }
}

fn register_source(cx: &mut Ctx, s: &DataSource) {
    let grid = match &s.kind {
        SourceKind::TileWms(t) => t.tile_grid.as_ref(),
        SourceKind::Wmts(w) => w.tile_grid.as_ref(),
        SourceKind::Xyz(x) => {
            if let Some(e) = x.extent.as_ref().and_then(|e| e.id) {
                cx.loaded.insert(("extent", e));
            }
            None
        }
        _ => None,
    };
    if let Some(g) = grid {
        if let Some(id) = g.id {
            cx.loaded.insert(("tilegrid", id));
        }
        if let Some(e) = g.extent.as_ref().and_then(|e| e.id) {
            cx.loaded.insert(("extent", e));
        }
    }
}

// ---------------------------------------------------------------------------
// output:only and filters (EntityUtil / findAllRestricted / findBySimpleFilter)
// ---------------------------------------------------------------------------

/// The restrictable fields named by `output:only` (case-insensitive key and
/// names). None means: no restriction (also when no name matches).
pub fn restrict_fields(params: &[(String, String)], res: Res) -> Option<Vec<&'static str>> {
    let mut requested: Vec<String> = Vec::new();
    let mut seen = false;
    for (k, v) in params {
        if k.eq_ignore_ascii_case("output:only") {
            seen = true;
            requested.extend(v.split(',').map(|s| s.trim().to_string()));
        }
    }
    if !seen {
        return None;
    }
    let mut out = Vec::new();
    for (name, _) in res.restrictable() {
        if requested.iter().any(|r| r.eq_ignore_ascii_case(name)) {
            out.push(*name);
        }
    }
    if out.is_empty() {
        None
    } else {
        Some(out)
    }
}

#[derive(Clone, Debug, PartialEq)]
pub enum Cast {
    I(i32),
    S(String),
    B(bool),
    D(f64),
}

/// `ConvertUtils.convert(value, type)`: an unparsable number or boolean
/// becomes the Java default (0, false).
pub fn cast(value: &str, t: FType) -> Cast {
    match t {
        FType::Int => Cast::I(value.trim().parse::<i32>().unwrap_or(0)),
        FType::Str => Cast::S(value.to_string()),
        FType::Bool => {
            let v = value.trim().to_ascii_lowercase();
            Cast::B(matches!(v.as_str(), "true" | "yes" | "y" | "on" | "1"))
        }
        FType::Dbl => Cast::D(value.trim().parse::<f64>().unwrap_or(0.0)),
    }
}

/// The equality conditions of a filter request. Each key that names a
/// restrictable field becomes an OR over its values; the keys are ANDed.
/// Returns None when no key is a valid field (the original returns no rows).
fn filter_conditions(params: &[(String, String)], res: Res) -> Option<Vec<(&'static str, Vec<Cast>)>> {
    let mut conds: Vec<(&'static str, Vec<Cast>)> = Vec::new();
    let mut keys: Vec<&str> = Vec::new();
    for (k, _) in params {
        if k == "output:only" {
            continue;
        }
        if !keys.contains(&k.as_str()) {
            keys.push(k);
        }
    }
    for key in keys {
        if let Some((name, t)) = res.restrictable().iter().find(|(n, _)| n.eq_ignore_ascii_case(key)) {
            let vals: Vec<Cast> = params
                .iter()
                .filter(|(k, _)| k == key)
                .map(|(_, v)| cast(v, *t))
                .collect();
            conds.push((name, vals));
        }
    }
    if conds.is_empty() {
        None
    } else {
        Some(conds)
    }
}

fn field_value(e: &Ent, field: &str) -> Option<Cast> {
    match e {
        Ent::User(u) => match field {
            "id" => u.id.map(Cast::I),
            "firstName" => u.first_name.clone().map(Cast::S),
            "lastName" => u.last_name.clone().map(Cast::S),
            "email" => u.email.clone().map(Cast::S),
            "accountName" => u.account_name.clone().map(Cast::S),
            "password" => u.password.clone().map(Cast::S),
            "active" => Some(Cast::B(u.active)),
            _ => None,
        },
        Ent::Group(g) => match field {
            "id" => g.id.map(Cast::I),
            "name" => g.name.clone().map(Cast::S),
            _ => None,
        },
        Ent::Role(r) => match field {
            "id" => r.id.map(Cast::I),
            "name" => r.name.clone().map(Cast::S),
            "description" => r.description.clone().map(Cast::S),
            _ => None,
        },
        Ent::Layer(l) => match field {
            "id" => l.id.map(Cast::I),
            "name" => l.name.clone().map(Cast::S),
            "description" => l.description.clone().map(Cast::S),
            _ => None,
        },
        Ent::Source(s) => match field {
            "id" => s.id.map(Cast::I),
            "name" => s.name.clone().map(Cast::S),
            "type" => s.type_.clone().map(Cast::S),
            "url" => s.url.clone().map(Cast::S),
            "format" => s.format.clone().map(Cast::S),
            _ => None,
        },
        Ent::Appearance(a) => match field {
            "id" => a.id.map(Cast::I),
            "attribution" => a.attribution.clone().map(Cast::S),
            "hoverable" => a.hoverable.map(Cast::B),
            "clickable" => a.clickable.map(Cast::B),
            "hoverTemplate" => a.hover_template.clone().map(Cast::S),
            "name" => a.name.clone().map(Cast::S),
            "maxResolution" => a.max_resolution.map(Cast::D),
            "minResolution" => a.min_resolution.map(Cast::D),
            "opacity" => a.opacity.map(Cast::D),
            "visible" => a.visible.map(Cast::B),
            _ => None,
        },
    }
}

/// Copy with only the listed fields set (`Transformers.aliasToBean` into a
/// new instance of the class, whose constructor defaults stay).
fn strip(e: &Ent, names: &[&str]) -> Ent {
    let has = |n: &str| names.contains(&n);
    match e {
        Ent::User(u) => {
            let mut s = User::default();
            if has("id") { s.id = u.id; }
            if has("firstName") { s.first_name = u.first_name.clone(); }
            if has("lastName") { s.last_name = u.last_name.clone(); }
            if has("email") { s.email = u.email.clone(); }
            if has("accountName") { s.account_name = u.account_name.clone(); }
            if has("password") { s.password = u.password.clone(); }
            if has("active") { s.active = u.active; }
            Ent::User(s)
        }
        Ent::Group(g) => {
            let mut s = Group::default();
            if has("id") { s.id = g.id; }
            if has("name") { s.name = g.name.clone(); }
            Ent::Group(s)
        }
        Ent::Role(r) => {
            let mut s = Role::default();
            if has("id") { s.id = r.id; }
            if has("name") { s.name = r.name.clone(); }
            if has("description") { s.description = r.description.clone(); }
            Ent::Role(s)
        }
        Ent::Layer(l) => {
            let mut s = Layer::default();
            if has("id") { s.id = l.id; }
            if has("name") { s.name = l.name.clone(); }
            if has("description") { s.description = l.description.clone(); }
            Ent::Layer(s)
        }
        Ent::Source(_) => unreachable!("data sources are refused before stripping"),
        Ent::Appearance(a) => {
            let mut s = Appearance::default();
            if has("id") { s.id = a.id; }
            if has("attribution") { s.attribution = a.attribution.clone(); }
            if has("hoverable") { s.hoverable = a.hoverable; }
            if has("clickable") { s.clickable = a.clickable; }
            if has("hoverTemplate") { s.hover_template = a.hover_template.clone(); }
            if has("name") { s.name = a.name.clone(); }
            if has("maxResolution") { s.max_resolution = a.max_resolution; }
            if has("minResolution") { s.min_resolution = a.min_resolution; }
            if has("opacity") { s.opacity = a.opacity; }
            if has("visible") { s.visible = a.visible; }
            Ent::Appearance(s)
        }
    }
}

async fn perms_for(cx: &mut Ctx, ids: &[i32]) -> db::DbRes<HashMap<i32, EntityPerms>> {
    if ids.is_empty() {
        return Ok(HashMap::new());
    }
    perms::load_perms(cx, Some(ids.to_vec())).await
}

fn empty_perms() -> EntityPerms {
    EntityPerms::default()
}

/// `findAllRestricted` / `findBySimpleFilter` with the READ post-filter.
async fn list(cx: &mut Ctx, p: &Principal, res: Res, params: &[(String, String)], filter: bool) -> Result<Vec<Value>, Status> {
    let restrict = restrict_fields(params, res);
    let mut ents = load_all(cx, res).await.map_err(|_| 500u16)?;
    if filter {
        match filter_conditions(params, res) {
            None => return Ok(Vec::new()),
            Some(conds) => ents.retain(|e| {
                conds
                    .iter()
                    .all(|(field, vals)| vals.iter().any(|v| field_value(e, field).as_ref() == Some(v)))
            }),
        }
    }
    let kind = res.kind();
    let kept: Vec<Ent> = match restrict {
        Some(names) => {
            if res == Res::Sources && !ents.is_empty() {
                // Hibernate instantiates the abstract LayerDataSource: Spring fails.
                return Err(500);
            }
            ents.iter()
                .map(|e| strip(e, &names))
                .filter(|e| allowed(p, kind, e.id(), &empty_perms(), Perm::Read, false))
                .collect()
        }
        None => {
            let ids: Vec<i32> = ents.iter().filter_map(|e| e.id()).collect();
            let perms = perms_for(cx, &ids).await.map_err(|_| 500u16)?;
            ents.into_iter()
                .filter(|e| {
                    let id = e.id();
                    let pm = id.and_then(|i| perms.get(&i)).cloned().unwrap_or_default();
                    allowed(p, kind, id, &pm, Perm::Read, true)
                })
                .collect()
        }
    };
    Ok(kept.iter().map(Ent::to_json).collect())
}

// ---------------------------------------------------------------------------
// Endpoints
// ---------------------------------------------------------------------------

pub async fn find_all(mut cx: Ctx, p: &Principal, res: Res, params: &[(String, String)]) -> Result<Value, Status> {
    let list = list(&mut cx, p, res, params, false).await?;
    Ok(Value::Array(list))
}

pub async fn find_filter(mut cx: Ctx, p: &Principal, res: Res, params: &[(String, String)]) -> Result<Value, Status> {
    let list = list(&mut cx, p, res, params, true).await?;
    Ok(Value::Array(list))
}

pub async fn find_by_id(mut cx: Ctx, p: &Principal, res: Res, id: i32) -> Result<Value, Status> {
    let ent = match load_one(&mut cx, res, id).await {
        Ok(Some(e)) => e,
        _ => return Err(404),
    };
    let perms = perms_for(&mut cx, &[id]).await.map_err(|_| 404u16)?;
    let pm = perms.get(&id).cloned().unwrap_or_default();
    if !allowed(p, res.kind(), Some(id), &pm, Perm::Read, true) {
        return Err(404);
    }
    Ok(ent.to_json())
}

/// Parses a new entity from a POST body (Jackson readValue with defaults).
fn parse_new(res: Res, v: &Value) -> jin::JRes<Ent> {
    Ok(match res {
        Res::Users => Ent::User(jin::user(v, User::default())?),
        Res::Groups => Ent::Group(jin::group(v, Group::default())?),
        Res::Roles => Ent::Role(jin::role(v, Role::default())?),
        Res::Layers => Ent::Layer(jin::layer(v, Layer::default())?),
        Res::Appearances => Ent::Appearance(jin::appearance(v, Appearance::default())?),
        // LayerDataSource is abstract: there is no way to build one from JSON.
        Res::Sources => return Err("Cannot construct instance of LayerDataSource".into()),
    })
}

async fn save_new(cx: &mut Ctx, ent: &mut Ent) -> db::DbRes<()> {
    match ent {
        Ent::User(u) => db::save_user(cx, u).await,
        Ent::Group(g) => db::save_group(cx, g).await,
        Ent::Role(r) => db::save_role(cx, r).await,
        Ent::Layer(l) => db::save_layer(cx, l, true).await,
        Ent::Appearance(a) => db::save_appearance(cx, a, true).await.map(|_| ()),
        Ent::Source(_) => Err("cannot create a LayerDataSource".into()),
    }
}

pub async fn create(mut cx: Ctx, p: &Principal, res: Res, body: &[u8]) -> Result<(Status, Value), Status> {
    let v: Value = serde_json::from_slice(body).map_err(|_| 400u16)?;
    let mut ent = parse_new(res, &v).map_err(|_| 400u16)?;
    if ent.id().is_some() {
        return Err(400);
    }
    // CREATE is granted to the super admin only: a new entity has no permission collections.
    if !p.is_admin() {
        return Err(400);
    }
    save_new(&mut cx, &mut ent).await.map_err(|_| 400u16)?;
    cx.tx.commit().await.map_err(|_| 400u16)?;
    Ok((201, ent.to_json()))
}

/// Jackson's `JsonNode.asInt()`.
fn node_as_int(v: &Value) -> i32 {
    match v {
        Value::Number(n) => n.as_i64().map(|i| i as i32).unwrap_or_else(|| n.as_f64().unwrap_or(0.0) as i32),
        Value::String(s) => s.trim().parse::<i32>().unwrap_or(0),
        Value::Bool(b) => *b as i32,
        _ => 0,
    }
}

fn apply_update(res: Res, v: &Value, ent: Ent) -> jin::JRes<Ent> {
    Ok(match (res, ent) {
        (Res::Users, Ent::User(u)) => Ent::User(jin::user(v, u)?),
        (Res::Groups, Ent::Group(g)) => Ent::Group(jin::group(v, g)?),
        (Res::Roles, Ent::Role(r)) => Ent::Role(jin::role(v, r)?),
        (Res::Layers, Ent::Layer(l)) => Ent::Layer(jin::layer(v, l)?),
        (Res::Sources, Ent::Source(s)) => Ent::Source(jin::data_source(v, s)?),
        (Res::Appearances, Ent::Appearance(a)) => Ent::Appearance(jin::appearance(v, a)?),
        _ => return Err("type mismatch".into()),
    })
}

pub async fn update(mut cx: Ctx, p: &Principal, res: Res, id: i32, body: &[u8]) -> Result<Value, Status> {
    let v: Value = serde_json::from_slice(body).map_err(|_| 404u16)?;
    // The body needs an "id" property equal to the path id.
    let obj = v.as_object().ok_or(400u16)?;
    let payload_id = obj.get("id").ok_or(400u16)?;
    if node_as_int(payload_id) != id {
        return Err(400);
    }
    let mut ent = match load_one(&mut cx, res, id).await {
        Ok(Some(e)) => e,
        _ => return Err(404),
    };
    let perms = perms_for(&mut cx, &[id]).await.map_err(|_| 404u16)?;
    let pm = perms.get(&id).cloned().unwrap_or_default();
    if !allowed(p, res.kind(), Some(id), &pm, Perm::Read, true) {
        return Err(404);
    }
    if !allowed(p, res.kind(), Some(id), &pm, Perm::Update, true) {
        return Err(404);
    }
    register_loaded(&mut cx, &ent);
    ent = apply_update(res, &v, ent).map_err(|_| 404u16)?;
    let fresh = |key: &str| obj.get(key).map_or(false, |x| !x.is_null());
    let saved: db::DbRes<()> = match &mut ent {
        Ent::User(u) => db::save_user(&mut cx, u).await,
        Ent::Group(g) => db::save_group(&mut cx, g).await,
        Ent::Role(r) => db::save_role(&mut cx, r).await,
        Ent::Layer(l) => {
            let f = fresh("appearance");
            db::save_layer(&mut cx, l, f).await
        }
        Ent::Source(s) => {
            let f = fresh("tileGrid");
            db::save_source(&mut cx, s, f).await
        }
        Ent::Appearance(a) => db::save_appearance(&mut cx, a, true).await.map(|_| ()),
    };
    saved.map_err(|_| 404u16)?;
    cx.tx.commit().await.map_err(|_| 404u16)?;
    Ok(ent.to_json())
}

pub async fn delete(mut cx: Ctx, p: &Principal, res: Res, id: i32) -> Result<Status, Status> {
    let ent = match load_one(&mut cx, res, id).await {
        Ok(Some(e)) => e,
        _ => return Err(404),
    };
    let perms = perms_for(&mut cx, &[id]).await.map_err(|_| 404u16)?;
    let pm = perms.get(&id).cloned().unwrap_or_default();
    if !allowed(p, res.kind(), Some(id), &pm, Perm::Read, true) {
        return Err(404);
    }
    if !allowed(p, res.kind(), Some(id), &pm, Perm::Delete, true) {
        return Err(404);
    }
    // LayerService.delete asks MapService.findMapsWithLayer, which is denied
    // to everyone but the super admin in the original.
    if res == Res::Layers && !p.is_admin() {
        return Err(404);
    }
    let done = match &ent {
        Ent::User(_) => db::delete_user(&mut cx, id).await,
        Ent::Group(_) => db::delete_group(&mut cx, id).await,
        Ent::Role(_) => db::delete_role(&mut cx, id).await,
        Ent::Layer(_) => db::delete_layer(&mut cx, id).await,
        Ent::Source(s) => db::delete_source(&mut cx, s).await,
        Ent::Appearance(_) => db::delete_appearance(&mut cx, id).await,
    };
    done.map_err(|_| 404u16)?;
    cx.tx.commit().await.map_err(|_| 404u16)?;
    Ok(204)
}

/// GET /users/{id}/userGroups: the user is not checked, its groups are
/// filtered by READ.
pub async fn user_groups(mut cx: Ctx, p: &Principal, user_id: i32) -> Result<Value, Status> {
    let user = match db::load_user(&mut cx, user_id).await {
        Ok(Some(u)) => u,
        _ => return Err(404),
    };
    let groups = if user.user_groups.is_empty() {
        Vec::new()
    } else {
        db::load_groups(&mut cx, Some(user.user_groups.clone())).await.map_err(|_| 404u16)?
    };
    let ids: Vec<i32> = groups.iter().filter_map(|g| g.id).collect();
    let perms = perms_for(&mut cx, &ids).await.map_err(|_| 404u16)?;
    let out: Vec<Value> = groups
        .iter()
        .filter(|g| {
            let pm = g.id.and_then(|i| perms.get(&i)).cloned().unwrap_or_default();
            allowed(p, Kind::Group, g.id, &pm, Perm::Read, true)
        })
        .map(jout::group)
        .collect();
    Ok(Value::Array(out))
}

/// GET /groups/{id}/users: the group is not checked, its members are filtered by READ.
pub async fn group_users(mut cx: Ctx, p: &Principal, group_id: i32) -> Result<Value, Status> {
    let group = match db::load_group(&mut cx, group_id).await {
        Ok(Some(g)) => g,
        _ => return Err(404),
    };
    let ids: Vec<i32> = group.members.iter().filter_map(|u| u.id).collect();
    let perms = perms_for(&mut cx, &ids).await.map_err(|_| 404u16)?;
    let out: Vec<Value> = group
        .members
        .iter()
        .filter(|u| {
            let pm = u.id.and_then(|i| perms.get(&i)).cloned().unwrap_or_default();
            allowed(p, Kind::User, u.id, &pm, Perm::Read, true)
        })
        .map(jout::user)
        .collect();
    Ok(Value::Array(out))
}

/// Restricted-list helper used by the HTTP layer for the errors of GET lists.
pub fn list_error(status: Status) -> Status {
    status
}

#[allow(dead_code)]
pub fn unused_marker(_: HashMap<i32, i32>) {}

tool_use_result.content:
//! The six resources and their endpoints (`AbstractRestController` and the
//! `users/{id}/userGroups` and `groups/{id}/users` sub-resources).
//!
//! Status codes follow the original's controllers: a failing POST is 400, a
//! failing PUT or DELETE and a missing or unreadable entity are 404, and the
//! `output:only` of a data source makes Spring answer 500.

use crate::db::{self, Ctx};
use crate::jin;
use crate::jout;
use crate::model::*;
use crate::perms::{self, allowed, EntityPerms, Kind, Perm, Principal};
use serde_json::Value;
use std::collections::HashMap;

pub type Status = u16;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Res {
    Users,
    Groups,
    Roles,
    Layers,
    Sources,
    Appearances,
}

/// Java field types of the restrictable (filterable) properties.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FType {
    Int,
    Str,
    Bool,
    Dbl,
}

impl Res {
    pub fn from_segment(s: &str) -> Option<Res> {
        Some(match s {
            "users" => Res::Users,
            "groups" => Res::Groups,
            "roles" => Res::Roles,
            "layers" => Res::Layers,
            "layerdatasources" => Res::Sources,
            "layerappearances" => Res::Appearances,
            _ => return None,
        })
    }

    pub fn kind(self) -> Kind {
        match self {
            Res::Users => Kind::User,
            Res::Groups => Kind::Group,
            Res::Roles | Res::Sources | Res::Appearances => Kind::AlwaysRead,
            Res::Layers => Kind::Layer,
        }
    }

    /// The non-static primitive, wrapper and String fields of the class
    /// hierarchy (`EntityUtil.getFilterableOrRestrictableFieldNames`).
    pub fn restrictable(self) -> &'static [(&'static str, FType)] {
        use FType::*;
        match self {
            Res::Users => &[
                ("id", Int), ("firstName", Str), ("lastName", Str), ("email", Str),
                ("accountName", Str), ("password", Str), ("active", Bool),
            ],
            Res::Groups => &[("id", Int), ("name", Str)],
            Res::Roles => &[("id", Int), ("name", Str), ("description", Str)],
            Res::Layers => &[("id", Int), ("name", Str), ("description", Str)],
            Res::Sources => &[("id", Int), ("name", Str), ("type", Str), ("url", Str), ("format", Str)],
            Res::Appearances => &[
                ("id", Int), ("attribution", Str), ("hoverable", Bool), ("clickable", Bool),
                ("hoverTemplate", Str), ("name", Str), ("maxResolution", Dbl), ("minResolution", Dbl),
                ("opacity", Dbl), ("visible", Bool),
            ],
        }
    }
}

/// An entity of one of the resources.
#[derive(Clone, Debug)]
pub enum Ent {
    User(User),
    Group(Group),
    Role(Role),
    Layer(Layer),
    Source(DataSource),
    Appearance(Appearance),
}

impl Ent {
    fn id(&self) -> Option<i32> {
        match self {
            Ent::User(e) => e.id,
            Ent::Group(e) => e.id,
            Ent::Role(e) => e.id,
            Ent::Layer(e) => e.id,
            Ent::Source(e) => e.id,
            Ent::Appearance(e) => e.id,
        }
    }

    fn to_json(&self) -> Value {
        match self {
            Ent::User(e) => jout::user(e),
            Ent::Group(e) => jout::group(e),
            Ent::Role(e) => jout::role(e),
            Ent::Layer(e) => jout::layer(e),
            Ent::Source(e) => jout::source(e),
            Ent::Appearance(e) => jout::appearance(e),
        }
    }
}

// ---------------------------------------------------------------------------
// Loading
// ---------------------------------------------------------------------------

async fn load_all(cx: &mut Ctx, res: Res) -> db::DbRes<Vec<Ent>> {
    Ok(match res {
        Res::Users => db::load_users(cx, None).await?.into_values().map(Ent::User).collect(),
        Res::Groups => db::load_groups(cx, None).await?.into_iter().map(Ent::Group).collect(),
        Res::Roles => db::load_roles(cx, None).await?.into_values().map(Ent::Role).collect(),
        Res::Layers => db::load_layers(cx, None).await?.into_iter().map(Ent::Layer).collect(),
        Res::Sources => db::load_sources(cx, None).await?.into_values().map(Ent::Source).collect(),
        Res::Appearances => db::load_appearances(cx, None).await?.into_values().map(Ent::Appearance).collect(),
    })
}

async fn load_one(cx: &mut Ctx, res: Res, id: i32) -> db::DbRes<Option<Ent>> {
    Ok(match res {
        Res::Users => db::load_user(cx, id).await?.map(Ent::User),
        Res::Groups => db::load_group(cx, id).await?.map(Ent::Group),
        Res::Roles => db::load_roles(cx, Some(vec![id])).await?.remove(&id).map(Ent::Role),
        Res::Layers => db::load_layer(cx, id).await?.map(Ent::Layer),
        Res::Sources => db::load_sources(cx, Some(vec![id])).await?.remove(&id).map(Ent::Source),
        Res::Appearances => db::load_appearances(cx, Some(vec![id])).await?.remove(&id).map(Ent::Appearance),
    })
}

/// Registers what the Hibernate session holds after `findById` of an entity:
/// the associations that are fetched eagerly (`@Fetch(FetchMode.JOIN)`).
fn register_loaded(cx: &mut Ctx, ent: &Ent) {
    match ent {
        Ent::Layer(l) => {
            if let Some(a) = l.appearance.as_ref().and_then(|a| a.id) {
                cx.loaded.insert(("appearance", a));
            }
            if let Some(s) = &l.source {
                register_source(cx, s);
            }
        }
        Ent::Source(s) => register_source(cx, s),
        _ => {}
    }
}

fn register_source(cx: &mut Ctx, s: &DataSource) {
    let grid = match &s.kind {
        SourceKind::TileWms(t) => t.tile_grid.as_ref(),
        SourceKind::Wmts(w) => w.tile_grid.as_ref(),
        SourceKind::Xyz(x) => {
            if let Some(e) = x.extent.as_ref().and_then(|e| e.id) {
                cx.loaded.insert(("extent", e));
            }
            None
        }
        _ => None,
    };
    if let Some(g) = grid {
        if let Some(id) = g.id {
            cx.loaded.insert(("tilegrid", id));
        }
        if let Some(e) = g.extent.as_ref().and_then(|e| e.id) {
            cx.loaded.insert(("extent", e));
        }
    }
}

// ---------------------------------------------------------------------------
// output:only and filters (EntityUtil / findAllRestricted / findBySimpleFilter)
// ---------------------------------------------------------------------------

/// The restrictable fields named by `output:only` (case-insensitive key and
/// names). None means: no restriction (also when no name matches).
pub fn restrict_fields(params: &[(String, String)], res: Res) -> Option<Vec<&'static str>> {
    let mut requested: Vec<String> = Vec::new();
    let mut seen = false;
    for (k, v) in params {
        if k.eq_ignore_ascii_case("output:only") {
            seen = true;
            requested.extend(v.split(',').map(|s| s.trim().to_string()));
        }
    }
    if !seen {
        return None;
    }
    let mut out = Vec::new();
    for (name, _) in res.restrictable() {
        if requested.iter().any(|r| r.eq_ignore_ascii_case(name)) {
            out.push(*name);
        }
    }
    if out.is_empty() {
        None
    } else {
        Some(out)
    }
}

#[derive(Clone, Debug, PartialEq)]
pub enum Cast {
    I(i32),
    S(String),
    B(bool),
    D(f64),
}

/// `ConvertUtils.convert(value, type)`: an unparsable number or boolean
/// becomes the Java default (0, false).
pub fn cast(value: &str, t: FType) -> Cast {
    match t {
        FType::Int => Cast::I(value.trim().parse::<i32>().unwrap_or(0)),
        FType::Str => Cast::S(value.to_string()),
        FType::Bool => {
            let v = value.trim().to_ascii_lowercase();
            Cast::B(matches!(v.as_str(), "true" | "yes" | "y" | "on" | "1"))
        }
        FType::Dbl => Cast::D(value.trim().parse::<f64>().unwrap_or(0.0)),
    }
}

/// The equality conditions of a filter request. Each key that names a
/// restrictable field becomes an OR over its values; the keys are ANDed.
/// Returns None when no key is a valid field (the original returns no rows).
fn filter_conditions(params: &[(String, String)], res: Res) -> Option<Vec<(&'static str, Vec<Cast>)>> {
    let mut conds: Vec<(&'static str, Vec<Cast>)> = Vec::new();
    let mut keys: Vec<&str> = Vec::new();
    for (k, _) in params {
        if k == "output:only" {
            continue;
        }
        if !keys.contains(&k.as_str()) {
            keys.push(k);
        }
    }
    for key in keys {
        if let Some((name, t)) = res.restrictable().iter().find(|(n, _)| n.eq_ignore_ascii_case(key)) {
            let vals: Vec<Cast> = params
                .iter()
                .filter(|(k, _)| k == key)
                .map(|(_, v)| cast(v, *t))
                .collect();
            conds.push((name, vals));
        }
    }
    if conds.is_empty() {
        None
    } else {
        Some(conds)
    }
}

fn field_value(e: &Ent, field: &str) -> Option<Cast> {
    match e {
        Ent::User(u) => match field {
            "id" => u.id.map(Cast::I),
            "firstName" => u.first_name.clone().map(Cast::S),
            "lastName" => u.last_name.clone().map(Cast::S),
            "email" => u.email.clone().map(Cast::S),
            "accountName" => u.account_name.clone().map(Cast::S),
            "password" => u.password.clone().map(Cast::S),
            "active" => Some(Cast::B(u.active)),
            _ => None,
        },
        Ent::Group(g) => match field {
            "id" => g.id.map(Cast::I),
            "name" => g.name.clone().map(Cast::S),
            _ => None,
        },
        Ent::Role(r) => match field {
            "id" => r.id.map(Cast::I),
            "name" => r.name.clone().map(Cast::S),
            "description" => r.description.clone().map(Cast::S),
            _ => None,
        },
        Ent::Layer(l) => match field {
            "id" => l.id.map(Cast::I),
            "name" => l.name.clone().map(Cast::S),
            "description" => l.description.clone().map(Cast::S),
            _ => None,
        },
        Ent::Source(s) => match field {
            "id" => s.id.map(Cast::I),
            "name" => s.name.clone().map(Cast::S),
            "type" => s.type_.clone().map(Cast::S),
            "url" => s.url.clone().map(Cast::S),
            "format" => s.format.clone().map(Cast::S),
            _ => None,
        },
        Ent::Appearance(a) => match field {
            "id" => a.id.map(Cast::I),
            "attribution" => a.attribution.clone().map(Cast::S),
            "hoverable" => a.hoverable.map(Cast::B),
            "clickable" => a.clickable.map(Cast::B),
            "hoverTemplate" => a.hover_template.clone().map(Cast::S),
            "name" => a.name.clone().map(Cast::S),
            "maxResolution" => a.max_resolution.map(Cast::D),
            "minResolution" => a.min_resolution.map(Cast::D),
            "opacity" => a.opacity.map(Cast::D),
            "visible" => a.visible.map(Cast::B),
            _ => None,
        },
    }
}

/// Copy with only the listed fields set (`Transformers.aliasToBean` into a
/// new instance of the class, whose constructor defaults stay).
fn strip(e: &Ent, names: &[&str]) -> Ent {
    let has = |n: &str| names.contains(&n);
    match e {
        Ent::User(u) => {
            let mut s = User::default();
            if has("id") { s.id = u.id; }
            if has("firstName") { s.first_name = u.first_name.clone(); }
            if has("lastName") { s.last_name = u.last_name.clone(); }
            if has("email") { s.email = u.email.clone(); }
            if has("accountName") { s.account_name = u.account_name.clone(); }
            if has("password") { s.password = u.password.clone(); }
            if has("active") { s.active = u.active; }
            Ent::User(s)
        }
        Ent::Group(g) => {
            let mut s = Group::default();
            if has("id") { s.id = g.id; }
            if has("name") { s.name = g.name.clone(); }
            Ent::Group(s)
        }
        Ent::Role(r) => {
            let mut s = Role::default();
            if has("id") { s.id = r.id; }
            if has("name") { s.name = r.name.clone(); }
            if has("description") { s.description = r.description.clone(); }
            Ent::Role(s)
        }
        Ent::Layer(l) => {
            let mut s = Layer::default();
            if has("id") { s.id = l.id; }
            if has("name") { s.name = l.name.clone(); }
            if has("description") { s.description = l.description.clone(); }
            Ent::Layer(s)
        }
        Ent::Source(_) => unreachable!("data sources are refused before stripping"),
        Ent::Appearance(a) => {
            let mut s = Appearance::default();
            if has("id") { s.id = a.id; }
            if has("attribution") { s.attribution = a.attribution.clone(); }
            if has("hoverable") { s.hoverable = a.hoverable; }
            if has("clickable") { s.clickable = a.clickable; }
            if has("hoverTemplate") { s.hover_template = a.hover_template.clone(); }
            if has("name") { s.name = a.name.clone(); }
            if has("maxResolution") { s.max_resolution = a.max_resolution; }
            if has("minResolution") { s.min_resolution = a.min_resolution; }
            if has("opacity") { s.opacity = a.opacity; }
            if has("visible") { s.visible = a.visible; }
            Ent::Appearance(s)
        }
    }
}

async fn perms_for(cx: &mut Ctx, ids: &[i32]) -> db::DbRes<HashMap<i32, EntityPerms>> {
    if ids.is_empty() {
        return Ok(HashMap::new());
    }
    perms::load_perms(cx, Some(ids.to_vec())).await
}

fn empty_perms() -> EntityPerms {
    EntityPerms::default()
}

/// `findAllRestricted` / `findBySimpleFilter` with the READ post-filter.
async fn list(cx: &mut Ctx, p: &Principal, res: Res, params: &[(String, String)], filter: bool) -> Result<Vec<Value>, Status> {
    let restrict = restrict_fields(params, res);
    let mut ents = load_all(cx, res).await.map_err(|_| 500u16)?;
    if filter {
        match filter_conditions(params, res) {
            None => return Ok(Vec::new()),
            Some(conds) => ents.retain(|e| {
                conds
                    .iter()
                    .all(|(field, vals)| vals.iter().any(|v| field_value(e, field).as_ref() == Some(v)))
            }),
        }
    }
    let kind = res.kind();
    let kept: Vec<Ent> = match restrict {
        Some(names) => {
            if res == Res::Sources && !ents.is_empty() {
                // Hibernate instantiates the abstract LayerDataSource: Spring fails.
                return Err(500);
            }
            ents.iter()
                .map(|e| strip(e, &names))
                .filter(|e| allowed(p, kind, e.id(), &empty_perms(), Perm::Read, false))
                .collect()
        }
        None => {
            let ids: Vec<i32> = ents.iter().filter_map(|e| e.id()).collect();
            let perms = perms_for(cx, &ids).await.map_err(|_| 500u16)?;
            ents.into_iter()
                .filter(|e| {
                    let id = e.id();
                    let pm = id.and_then(|i| perms.get(&i)).cloned().unwrap_or_default();
                    allowed(p, kind, id, &pm, Perm::Read, true)
                })
                .collect()
        }
    };
    Ok(kept.iter().map(Ent::to_json).collect())
}

// ---------------------------------------------------------------------------
// Endpoints
// ---------------------------------------------------------------------------

pub async fn find_all(mut cx: Ctx, p: &Principal, res: Res, params: &[(String, String)]) -> Result<Value, Status> {
    let list = list(&mut cx, p, res, params, false).await?;
    Ok(Value::Array(list))
}

pub async fn find_filter(mut cx: Ctx, p: &Principal, res: Res, params: &[(String, String)]) -> Result<Value, Status> {
    let list = list(&mut cx, p, res, params, true).await?;
    Ok(Value::Array(list))
}

pub async fn find_by_id(mut cx: Ctx, p: &Principal, res: Res, id: i32) -> Result<Value, Status> {
    let ent = match load_one(&mut cx, res, id).await {
        Ok(Some(e)) => e,
        _ => return Err(404),
    };
    let perms = perms_for(&mut cx, &[id]).await.map_err(|_| 404u16)?;
    let pm = perms.get(&id).cloned().unwrap_or_default();
    if !allowed(p, res.kind(), Some(id), &pm, Perm::Read, true) {
        return Err(404);
    }
    Ok(ent.to_json())
}

/// Parses a new entity from a POST body (Jackson readValue with defaults).
fn parse_new(res: Res, v: &Value) -> jin::JRes<Ent> {
    Ok(match res {
        Res::Users => Ent::User(jin::user(v, User::default())?),
        Res::Groups => Ent::Group(jin::group(v, Group::default())?),
        Res::Roles => Ent::Role(jin::role(v, Role::default())?),
        Res::Layers => Ent::Layer(jin::layer(v, Layer::default())?),
        Res::Appearances => Ent::Appearance(jin::appearance(v, Appearance::default())?),
        // LayerDataSource is abstract: there is no way to build one from JSON.
        Res::Sources => return Err("Cannot construct instance of LayerDataSource".into()),
    })
}

async fn save_new(cx: &mut Ctx, ent: &mut Ent) -> db::DbRes<()> {
    match ent {
        Ent::User(u) => db::save_user(cx, u).await,
        Ent::Group(g) => db::save_group(cx, g).await,
        Ent::Role(r) => db::save_role(cx, r).await,
        Ent::Layer(l) => db::save_layer(cx, l, true).await,
        Ent::Appearance(a) => db::save_appearance(cx, a, true).await.map(|_| ()),
        Ent::Source(_) => Err("cannot create a LayerDataSource".into()),
    }
}

pub async fn create(mut cx: Ctx, p: &Principal, res: Res, body: &[u8]) -> Result<(Status, Value), Status> {
    let v: Value = serde_json::from_slice(body).map_err(|_| 400u16)?;
    let mut ent = parse_new(res, &v).map_err(|_| 400u16)?;
    if ent.id().is_some() {
        return Err(400);
    }
    // CREATE is granted to the super admin only: a new entity has no permission collections.
    if !p.is_admin() {
        return Err(400);
    }
    save_new(&mut cx, &mut ent).await.map_err(|_| 400u16)?;
    cx.tx.commit().await.map_err(|_| 400u16)?;
    Ok((201, ent.to_json()))
}

/// Jackson's `JsonNode.asInt()`.
fn node_as_int(v: &Value) -> i32 {
    match v {
        Value::Number(n) => n.as_i64().map(|i| i as i32).unwrap_or_else(|| n.as_f64().unwrap_or(0.0) as i32),
        Value::String(s) => s.trim().parse::<i32>().unwrap_or(0),
        Value::Bool(b) => *b as i32,
        _ => 0,
    }
}

fn apply_update(res: Res, v: &Value, ent: Ent) -> jin::JRes<Ent> {
    Ok(match (res, ent) {
        (Res::Users, Ent::User(u)) => Ent::User(jin::user(v, u)?),
        (Res::Groups, Ent::Group(g)) => Ent::Group(jin::group(v, g)?),
        (Res::Roles, Ent::Role(r)) => Ent::Role(jin::role(v, r)?),
        (Res::Layers, Ent::Layer(l)) => Ent::Layer(jin::layer(v, l)?),
        (Res::Sources, Ent::Source(s)) => Ent::Source(jin::data_source(v, s)?),
        (Res::Appearances, Ent::Appearance(a)) => Ent::Appearance(jin::appearance(v, a)?),
        _ => return Err("type mismatch".into()),
    })
}

pub async fn update(mut cx: Ctx, p: &Principal, res: Res, id: i32, body: &[u8]) -> Result<Value, Status> {
    let v: Value = serde_json::from_slice(body).map_err(|_| 404u16)?;
    // The body needs an "id" property equal to the path id.
    let obj = v.as_object().ok_or(400u16)?;
    let payload_id = obj.get("id").ok_or(400u16)?;
    if node_as_int(payload_id) != id {
        return Err(400);
    }
    let mut ent = match load_one(&mut cx, res, id).await {
        Ok(Some(e)) => e,
        _ => return Err(404),
    };
    let perms = perms_for(&mut cx, &[id]).await.map_err(|_| 404u16)?;
    let pm = perms.get(&id).cloned().unwrap_or_default();
    if !allowed(p, res.kind(), Some(id), &pm, Perm::Read, true) {
        return Err(404);
    }
    if !allowed(p, res.kind(), Some(id), &pm, Perm::Update, true) {
        return Err(404);
    }
    register_loaded(&mut cx, &ent);
    ent = apply_update(res, &v, ent).map_err(|_| 404u16)?;
    let fresh = |key: &str| obj.get(key).map_or(false, |x| !x.is_null());
    let saved: db::DbRes<()> = match &mut ent {
        Ent::User(u) => db::save_user(&mut cx, u).await,
        Ent::Group(g) => db::save_group(&mut cx, g).await,
        Ent::Role(r) => db::save_role(&mut cx, r).await,
        Ent::Layer(l) => {
            let f = fresh("appearance");
            db::save_layer(&mut cx, l, f).await
        }
        Ent::Source(s) => {
            let f = fresh("tileGrid");
            db::save_source(&mut cx, s, f).await
        }
        Ent::Appearance(a) => db::save_appearance(&mut cx, a, true).await.map(|_| ()),
    };
    saved.map_err(|_| 404u16)?;
    cx.tx.commit().await.map_err(|_| 404u16)?;
    Ok(ent.to_json())
}

pub async fn delete(mut cx: Ctx, p: &Principal, res: Res, id: i32) -> Result<Status, Status> {
    let ent = match load_one(&mut cx, res, id).await {
        Ok(Some(e)) => e,
        _ => return Err(404),
    };
    let perms = perms_for(&mut cx, &[id]).await.map_err(|_| 404u16)?;
    let pm = perms.get(&id).cloned().unwrap_or_default();
    if !allowed(p, res.kind(), Some(id), &pm, Perm::Read, true) {
        return Err(404);
    }
    if !allowed(p, res.kind(), Some(id), &pm, Perm::Delete, true) {
        return Err(404);
    }
    // LayerService.delete asks MapService.findMapsWithLayer, which is denied
    // to everyone but the super admin in the original.
    if res == Res::Layers && !p.is_admin() {
        return Err(404);
    }
    let done = match &ent {
        Ent::User(_) => db::delete_user(&mut cx, id).await,
        Ent::Group(_) => db::delete_group(&mut cx, id).await,
        Ent::Role(_) => db::delete_role(&mut cx, id).await,
        Ent::Layer(_) => db::delete_layer(&mut cx, id).await,
        Ent::Source(s) => db::delete_source(&mut cx, s).await,
        Ent::Appearance(_) => db::delete_appearance(&mut cx, id).await,
    };
    done.map_err(|_| 404u16)?;
    cx.tx.commit().await.map_err(|_| 404u16)?;
    Ok(204)
}

/// GET /users/{id}/userGroups: the user is not checked, its groups are
/// filtered by READ.
pub async fn user_groups(mut cx: Ctx, p: &Principal, user_id: i32) -> Result<Value, Status> {
    let user = match db::load_user(&mut cx, user_id).await {
        Ok(Some(u)) => u,
        _ => return Err(404),
    };
    let groups = if user.user_groups.is_empty() {
        Vec::new()
    } else {
        db::load_groups(&mut cx, Some(user.user_groups.clone())).await.map_err(|_| 404u16)?
    };
    let ids: Vec<i32> = groups.iter().filter_map(|g| g.id).collect();
    let perms = perms_for(&mut cx, &ids).await.map_err(|_| 404u16)?;
    let out: Vec<Value> = groups
        .iter()
        .filter(|g| {
            let pm = g.id.and_then(|i| perms.get(&i)).cloned().unwrap_or_default();
            allowed(p, Kind::Group, g.id, &pm, Perm::Read, true)
        })
        .map(jout::group)
        .collect();
    Ok(Value::Array(out))
}

/// GET /groups/{id}/users: the group is not checked, its members are filtered by READ.
pub async fn group_users(mut cx: Ctx, p: &Principal, group_id: i32) -> Result<Value, Status> {
    let group = match db::load_group(&mut cx, group_id).await {
        Ok(Some(g)) => g,
        _ => return Err(404),
    };
    let ids: Vec<i32> = group.members.iter().filter_map(|u| u.id).collect();
    let perms = perms_for(&mut cx, &ids).await.map_err(|_| 404u16)?;
    let out: Vec<Value> = group
        .members
        .iter()
        .filter(|u| {
            let pm = u.id.and_then(|i| perms.get(&i)).cloned().unwrap_or_default();
            allowed(p, Kind::User, u.id, &pm, Perm::Read, true)
        })
        .map(jout::user)
        .collect();
    Ok(Value::Array(out))
}

/// Restricted-list helper used by the HTTP layer for the errors of GET lists.
pub fn list_error(status: Status) -> Status {
    status
}

#[allow(dead_code)]
pub fn unused_marker(_: HashMap<i32, i32>) {}

