//! HTTP layer: HTTP Basic authentication (the Spring Security filter chain of
//! `/rest/**`), routing of the REST paths, and the response shapes.

use crate::db::{self, Ctx};
use crate::perms::Principal;
use crate::resources::{self, Res, Status};
use axum::body::{to_bytes, Body};
use axum::extract::Request;
use axum::http::{header, HeaderValue, Method, StatusCode};
use axum::response::Response;
use base64::Engine;
use serde_json::Value;
use sqlx::PgPool;
use std::collections::HashSet;

const MAX_BODY: usize = 16 * 1024 * 1024;

fn empty(status: u16) -> Response {
    let mut resp = Response::new(Body::empty());
    *resp.status_mut() = StatusCode::from_u16(status).unwrap_or(StatusCode::INTERNAL_SERVER_ERROR);
    if status == 401 {
        resp.headers_mut().insert(
            header::WWW_AUTHENTICATE,
            HeaderValue::from_static("Basic realm=\"SHOGun Realm\""),
        );
    }
    resp
}

fn json(status: u16, body: &Value) -> Response {
    let mut resp = Response::new(Body::from(body.to_string()));
    *resp.status_mut() = StatusCode::from_u16(status).unwrap_or(StatusCode::OK);
    resp.headers_mut().insert(
        header::CONTENT_TYPE,
        HeaderValue::from_static("application/json;charset=UTF-8"),
    );
    resp
}

async fn new_ctx(pool: &PgPool) -> Result<Ctx, sqlx::Error> {
    Ok(Ctx {
        tx: pool.begin().await?,
        ids: pool.acquire().await?,
        loaded: HashSet::new(),
    })
}

/// Spring's BasicAuthenticationFilter with the ShogunCoreAuthenticationProvider
/// and the bcrypt password encoder. Failed credentials and accounts without
/// any granted authority give 401; a valid account without ROLE_USER gives 403.
pub async fn authenticate(cx: &mut Ctx, header_value: Option<&str>) -> Result<Principal, Status> {
    let h = header_value.ok_or(401u16)?;
    if h.len() < 6 || !h[..6].eq_ignore_ascii_case("basic ") {
        return Err(401);
    }
    let raw = base64::engine::general_purpose::STANDARD
        .decode(h[6..].trim())
        .map_err(|_| 401u16)?;
    let text = String::from_utf8(raw).map_err(|_| 401u16)?;
    let (account, password) = text.split_once(':').ok_or(401u16)?;
    let (id, active, hash) = db::account(cx, account)
        .await
        .map_err(|_| 500u16)?
        .ok_or(401u16)?;
    if !active {
        return Err(401);
    }
    let matches = match &hash {
        Some(h) => bcrypt::verify(password, h).unwrap_or(false),
        None => false,
    };
    if !matches {
        return Err(401);
    }
    let authorities = db::authorities(cx, id).await.map_err(|_| 500u16)?;
    if authorities.is_empty() {
        return Err(401);
    }
    let groups = db::user_group_ids(cx, id).await.map_err(|_| 500u16)?;
    let principal = Principal { id, authorities, groups };
    if !principal.has_user_role() {
        return Err(403);
    }
    Ok(principal)
}

fn parse_id(s: &str) -> Result<i32, Status> {
    // Spring converts the path variable to int: anything else is a 400.
    s.parse::<i32>().map_err(|_| 400u16)
}

enum Route<'a> {
    Collection(Res),
    Filter(Res),
    Item(Res, &'a str),
    UserGroups(&'a str),
    GroupUsers(&'a str),
}

fn route<'a>(segs: &[&'a str]) -> Option<Route<'a>> {
    match segs {
        [r] => Some(Route::Collection(Res::from_segment(r)?)),
        [r, "filter"] => Some(Route::Filter(Res::from_segment(r)?)),
        [r, id] => {
            let res = Res::from_segment(r)?;
            Some(Route::Item(res, id))
        }
        ["users", id, "userGroups"] => Some(Route::UserGroups(id)),
        ["groups", id, "users"] => Some(Route::GroupUsers(id)),
        _ => None,
    }
}

async fn dispatch(
    cx: Ctx,
    p: &Principal,
    method: &Method,
    segs: &[&str],
    params: &[(String, String)],
    body: &[u8],
) -> Response {
    let r = match route(segs) {
        Some(r) => r,
        None => return empty(404),
    };
    let result: Result<Response, Status> = match (method.as_str(), r) {
        ("GET", Route::Collection(res)) => resources::find_all(cx, p, res, params)
            .await
            .map(|v| json(200, &v)),
        ("POST", Route::Collection(res)) => resources::create(cx, p, res, body)
            .await
            .map(|(s, v)| json(s, &v)),
        ("GET", Route::Filter(res)) => resources::find_filter(cx, p, res, params)
            .await
            .map(|v| json(200, &v)),
        ("GET", Route::Item(res, id)) => match parse_id(id) {
            Err(c) => Err(c),
            Ok(id) => resources::find_by_id(cx, p, res, id).await.map(|v| json(200, &v)),
        },
        ("PUT", Route::Item(res, id)) => match parse_id(id) {
            Err(c) => Err(c),
            Ok(id) => resources::update(cx, p, res, id, body).await.map(|v| json(200, &v)),
        },
        ("DELETE", Route::Item(res, id)) => match parse_id(id) {
            Err(c) => Err(c),
            Ok(id) => resources::delete(cx, p, res, id).await.map(|s| empty(s)),
        },
        ("GET", Route::UserGroups(id)) => match parse_id(id) {
            Err(c) => Err(c),
            Ok(id) => resources::user_groups(cx, p, id).await.map(|v| json(200, &v)),
        },
        ("GET", Route::GroupUsers(id)) => match parse_id(id) {
            Err(c) => Err(c),
            Ok(id) => resources::group_users(cx, p, id).await.map(|v| json(200, &v)),
        },
        _ => return empty(405),
    };
    match result {
        Ok(resp) => resp,
        Err(code) => empty(code),
    }
}

/// Entry point for every request.
pub async fn handle(pool: PgPool, req: Request) -> Response {
    let (parts, body) = req.into_parts();
    let path = parts.uri.path().to_string();
    let rest = match path.strip_prefix("/rest") {
        Some(r) if r.is_empty() || r.starts_with('/') => r.to_string(),
        _ => return empty(404),
    };
    let segs: Vec<&str> = rest.split('/').filter(|s| !s.is_empty()).collect();
    let params: Vec<(String, String)> = url::form_urlencoded::parse(parts.uri.query().unwrap_or("").as_bytes())
        .map(|(k, v)| (k.into_owned(), v.into_owned()))
        .collect();

    let mut cx = match new_ctx(&pool).await {
        Ok(cx) => cx,
        Err(_) => return empty(500),
    };
    let auth_header = parts
        .headers
        .get(header::AUTHORIZATION)
        .and_then(|v| v.to_str().ok());
    let principal = match authenticate(&mut cx, auth_header).await {
        Ok(p) => p,
        Err(code) => return empty(code),
    };
    let body_bytes = match to_bytes(body, MAX_BODY).await {
        Ok(b) => b,
        Err(_) => return empty(400),
    };
    dispatch(cx, &principal, &parts.method, &segs, &params, &body_bytes).await
}

