//! SHOGun-Core REST slice (`/rest/users`, `/rest/groups`, `/rest/roles`,
//! `/rest/layers`, `/rest/layerdatasources`, `/rest/layerappearances`) as a
//! standalone service on the same PostgreSQL schema as the Java original.
//!
//! Configuration: `DATABASE_URL` (PostgreSQL URL) and `PORT` (listen port,
//! on all interfaces).

mod db;
mod http;
mod jin;
mod jout;
mod model;
mod perms;
mod resources;

use axum::extract::Request;
use axum::Router;
use sqlx::postgres::PgPoolOptions;
use std::net::SocketAddr;

#[tokio::main]
async fn main() {
    let database_url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
        eprintln!("DATABASE_URL is not set");
        std::process::exit(2);
    });
    let port: u16 = std::env::var("PORT")
        .ok()
        .and_then(|p| p.trim().parse().ok())
        .unwrap_or(8080);

    // Lazy: the service starts answering at once and connects on first use.
    let pool = PgPoolOptions::new()
        .max_connections(16)
        .connect_lazy(&database_url)
        .unwrap_or_else(|e| {
            eprintln!("invalid DATABASE_URL: {e}");
            std::process::exit(2);
        });

    let app = Router::new().fallback(move |req: Request| {
        let pool = pool.clone();
        async move { http::handle(pool, req).await }
    });

    let addr = SocketAddr::from(([0, 0, 0, 0], port));
    let listener = tokio::net::TcpListener::bind(addr)
        .await
        .unwrap_or_else(|e| {
            eprintln!("cannot bind {addr}: {e}");
            std::process::exit(1);
        });
    eprintln!("listening on {addr}");
    axum::serve(listener, app).await.expect("server error");
}

