#!/usr/bin/env python3
"""Differential test: the same requests against the Java original and the Rust port.

Each scenario resets both databases to the same seed, runs the steps against
both servers, and compares status codes, normalised JSON bodies and the rows of
the tables the scenario may write.
"""
import base64
import json
import subprocess
import sys
import urllib.request
import urllib.error

REF = "http://localhost:8081/rest"
PORT = "http://localhost:9090/rest"
DBS = {"ref": REF, "port": PORT}

TABLES = [
    "persons", "users", "roles", "usergroups", "user_usergroup", "users_roles", "usergroups_roles",
    "layers", "layerdatasources", "imagewmslayerdatasources", "tilewmslayerdatasources",
    "wfslayerdatasources", "wmtslayerdatasources", "wmtslayerdatasources_urls", "xyzlayerdatasources",
    "layerappearances", "layerappearances_properties", "tilegrids", "tilegrid_resolution",
    "wmtstilegrids", "wmtstilegrids_matrixids", "extents", "userpermissions", "grouppermissions",
    "permissioncollections", "permissioncollections_permissions", "hibernate_sequences", "maps_layers",
]

# columns that are not compared (timestamps)
SKIP_COLS = {"created", "modified"}


def sh(cmd):
    return subprocess.run(cmd, shell=True, capture_output=True, text=True)


def reset(db):
    sh(f"pg_restore --clean --if-exists --no-owner -d {db} /tmp/ref_seed.dump")


def psql_rows(db, table):
    cols = sh(
        f"psql -d {db} -At -c \"select column_name from information_schema.columns "
        f"where table_schema='public' and table_name='{table}' order by ordinal_position\""
    ).stdout.split()
    cols = [c for c in cols if c not in SKIP_COLS]
    if not cols:
        return []
    sel = ", ".join(f"coalesce({c}::text,'<null>')" for c in cols)
    out = sh(f"psql -d {db} -At -F '|' -c \"select {sel} from {table}\"").stdout
    rows = [r for r in out.split("\n") if r != ""]
    return sorted(rows)


def dump(db):
    return {t: psql_rows(db, t) for t in TABLES}


def request(base, method, path, cred, body):
    url = base + path
    data = None
    headers = {}
    if cred:
        headers["Authorization"] = "Basic " + base64.b64encode(cred.encode()).decode()
    if body is not None:
        data = body.encode() if isinstance(body, str) else json.dumps(body).encode()
        headers["Content-Type"] = "application/json"
    req = urllib.request.Request(url, data=data, method=method, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=60) as resp:
            code = resp.status
            raw = resp.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as e:
        code = e.code
        raw = e.read().decode("utf-8", "replace")
    parsed = None
    if raw.strip():
        try:
            parsed = json.loads(raw)
        except ValueError:
            parsed = "<non-json>"
    return code, parsed


def norm(v):
    """Order-insensitive normal form: sort lists by their canonical JSON."""
    if isinstance(v, dict):
        return {k: norm(x) for k, x in v.items()}
    if isinstance(v, list):
        items = [norm(x) for x in v]
        return sorted(items, key=lambda x: json.dumps(x, sort_keys=True))
    return v


def run_steps(scn, steps):
    results = []
    for st in steps:
        if st[0] == "sql":
            for db in ("ref", "port"):
                sh(f"psql -d {db} -q -v ON_ERROR_STOP=0 -c \"{st[1]}\"")
            results.append(("sql", None))
            continue
        method, path, cred, body = st
        per = {}
        for name, base in DBS.items():
            per[name] = request(base, method, path, cred, body)
        results.append(per)
    return results


def compare(scn_name, steps, check_db=True):
    reset("ref")
    reset("port")
    res = run_steps(scn_name, steps)
    ok = True
    report = []
    for st, r in zip(steps, res):
        if st[0] == "sql":
            continue
        a = r["ref"]
        b = r["port"]
        label = f"{st[0]} {st[1]} as {st[2] or 'anon'} body={json.dumps(st[3])[:100] if st[3] is not None else '-'}"
        same_code = a[0] == b[0]
        same_body = norm(a[1]) == norm(b[1])
        if not (same_code and same_body):
            ok = False
            report.append(f"  STEP {label}\n    ref : {a[0]} {json.dumps(a[1])[:600]}\n    port: {b[0]} {json.dumps(b[1])[:600]}")
        else:
            report.append(f"  ok   {label} -> {a[0]}")
    if check_db:
        dref = dump("ref")
        dport = dump("port")
        for t in TABLES:
            if dref[t] != dport[t]:
                ok = False
                report.append(f"  DB DIFF {t}:\n    ref : {dref[t][:20]}\n    port: {dport[t][:20]}")
    return ok, report


if __name__ == "__main__":
    import scenarios
    only = sys.argv[1:]
    total = 0
    failed = []
    for name, steps in scenarios.SCENARIOS:
        if only and not any(o in name for o in only):
            continue
        total += 1
        ok, report = compare(name, steps)
        status = "PASS" if ok else "FAIL"
        print(f"[{status}] {name}")
        if not ok or "-v" in sys.argv:
            print("\n".join(report))
        if not ok:
            failed.append(name)
    print(f"\n{total - len(failed)}/{total} scenarios pass")
    if failed:
        print("failed:", ", ".join(failed))

