//! Unit tests of the mapping rules (no database needed).

use crate::db::{convert_property_value, java_double_bytes, java_double_from_bytes, java_double_text, property_value_text};
use crate::jin;
use crate::jout;
use crate::model::*;
use crate::perms::{allowed, parse_perm, EntityPerms, Kind, Perm, Principal};
use crate::resources::{cast, restrict_fields, Cast, FType, Res};
use serde_json::json;
use std::collections::{HashMap, HashSet};

fn principal(id: i32, authorities: &[&str], groups: &[i32]) -> Principal {
    Principal {
        id,
        authorities: authorities.iter().map(|s| s.to_string()).collect(),
        groups: groups.iter().copied().collect::<HashSet<i32>>(),
    }
}

#[test]
fn unknown_property_is_refused_but_ignored_ones_pass() {
    assert!(jin::role(&json!({"name": "x", "foo": 1}), Role::default()).is_err());
    let r = jin::role(&json!({"name": "x", "created": "2020-01-01", "modified": null}), Role::default()).unwrap();
    assert_eq!(r.name.as_deref(), Some("x"));
    let u = jin::user(&json!({"accountName": "a", "userPermissions": {}, "groupPermissions": []}), User::default());
    assert!(u.is_ok());
}

#[test]
fn numeric_strings_and_null_primitives_are_coerced() {
    let r = jin::role(&json!({"id": "7", "name": 5}), Role::default()).unwrap();
    assert_eq!(r.id, Some(7));
    assert_eq!(r.name.as_deref(), Some("5"));
    let u = jin::user(&json!({"active": null}), User::default()).unwrap();
    assert!(!u.active);
    let ds = jin::data_source(
        &json!({"width": null}),
        DataSource {
            id: Some(1),
            name: None,
            type_: None,
            url: None,
            format: None,
            kind: SourceKind::ImageWms(ImageWms { width: 9, ..Default::default() }),
        },
    )
    .unwrap();
    match ds.kind {
        SourceKind::ImageWms(i) => assert_eq!(i.width, 0),
        _ => panic!("kind changed"),
    }
}

#[test]
fn bare_role_objects_collapse_in_a_set() {
    // `equals` of Role ignores the id: [{id:1},{id:2}] keeps one element.
    let u = jin::user(&json!({"roles": [{"id": 1}, {"id": 2}]}), User::default()).unwrap();
    assert_eq!(u.roles.len(), 1);
    assert_eq!(u.roles[0].id, Some(1));
    let u = jin::user(&json!({"roles": [{"id": 1, "name": "A"}, {"id": 2, "name": "B"}]}), User::default()).unwrap();
    assert_eq!(u.roles.len(), 2);
}

#[test]
fn group_members_collapse_like_java_equals() {
    let g = jin::group(&json!({"members": [{"id": 3}, {"id": 4}]}), Group::default()).unwrap();
    assert_eq!(g.members.len(), 1);
    assert_eq!(g.members[0].id, Some(3));
}

#[test]
fn user_groups_are_ids_and_dedupe() {
    let u = jin::user(&json!({"userGroups": [5, 5, 6]}), User::default()).unwrap();
    assert_eq!(u.user_groups, vec![5, 6]);
    assert!(jin::user(&json!({"userGroups": [null]}), User::default()).is_err());
}

#[test]
fn abstract_data_source_cannot_be_set_on_a_layer() {
    assert!(jin::layer(&json!({"name": "x", "source": {"id": 1}}), Layer::default()).is_err());
    assert!(jin::layer(&json!({"name": "x", "source": null}), Layer::default()).is_ok());
}

#[test]
